use std::fs;
use std::time::SystemTime;
#[derive(Clone)] struct E { name: String, t: SystemTime, size: u64 }
fn collect(dir: &str) -> Vec<E> {
    fs::read_dir(dir).unwrap().filter_map(|e| e.ok()).map(|e| {
        let md = e.metadata().unwrap();
        E{ name: e.file_name().to_string_lossy().to_string(), t: md.modified().unwrap(), size: md.len() }
    }).collect()
}
fn show(v:&[E]) -> String { v.iter().map(|e| e.name.clone()).collect::<Vec<_>>().join(",") }
fn main(){
    let dir = std::env::args().nth(1).unwrap();
    let base = collect(&dir);
    let filtered: Vec<E> = base.iter().filter(|e| !e.name.starts_with('.')).filter(|e| e.name!="broken").cloned().collect();
    println!("input:      {}", show(&filtered));
    let mut v = filtered.clone(); v.sort_by(|a,b| a.t.cmp(&b.t)); println!("stable asc: {}", show(&v));
    let mut v = filtered.clone(); v.sort_unstable_by(|a,b| a.t.cmp(&b.t)); println!("unsrt asc:  {}", show(&v));
    let mut v = filtered.clone(); v.reverse(); v.sort_by(|a,b| a.t.cmp(&b.t)); println!("rev stable asc: {}", show(&v));
    let mut v = filtered.clone(); v.sort_by(|a,b| b.t.cmp(&a.t)); v.reverse(); println!("stable desc then rev: {}", show(&v));
    let mut v = filtered.clone(); v.sort_unstable_by(|a,b| a.t.cmp(&b.t)); v.reverse(); println!("unsrt asc then rev: {}", show(&v));
    let mut v = filtered.clone(); v.reverse(); v.sort_unstable_by(|a,b| a.t.cmp(&b.t)); println!("rev unsrt asc: {}", show(&v));
}
EOF
