{"command": "cat <<'PY' > /tmp/h/h.py
import subprocess,sys,time,socket,re,os,json
def freeport():
    s=socket.socket(); s.bind(('127.0.0.1',0)); p=s.getsockname()[1]; s.close(); return p
class Srv:
    def __init__(self,*args,path=None):
        self.port=freeport()
        cmd=['./executable','-p',str(self.port)]+list(args)
        if path: cmd.append(path)
        self.log=open('/tmp/h/srv_%d.log'%self.port,'wb')
        self.p=subprocess.Popen(cmd,cwd='/workspace',stdout=self.log,stderr=subprocess.STDOUT)
        time.sleep(0.7)
    def req(self,path,method='GET',headers=None,data=None):
        import urllib.request,urllib.error
        url='http://127.0.0.1:%d%s'%(self.port,path)
        r=urllib.request.Request(url,method=method,data=data)
        if headers:
            for k,v in headers.items(): r.add_header(k,v)
        try:
            resp=urllib.request.urlopen(r)
        except urllib.error.HTTPError as e:
            resp=e
        hdrs=[(k.lower(),v) for k,v in resp.headers.items()]
        body=resp.read()
        return resp.status, hdrs, body
    def show(self,path,**kw):
        st,h,b=self.req(path,**kw)
        print("=== %s -> %d"%(path,st))
        for k,v in h: print("  %s: %s"%(k,v.decode() if isinstance(v,bytes) else v))
        if len(b)<600: print("  BODY:",b[:600])
        else: print("  BODY: (%d bytes) %s..."%(len(b),b[:200]))
        return st,h,b
    def stop(self):
        self.p.terminate()
