{"command": "cd /workspace && cat > src/main.rs <<'EOF'
mod assets;
mod archive;
mod cli;
mod config;
mod handler;
mod http;
mod listing;
mod md;
mod mime;
mod qr;
mod render;
mod server;
mod tls;
mod upload;
mod util;
mod webdav;

use clap::Command;
use std::process::exit;

fn main() {
    let cmd = cli::command();
    let matches = match cmd.clone().try_get_matches_from(std::env::args_os()) {
        Ok(m) => m,
        Err(e) => {
            let use_stderr = e.use_stderr();
            let _ = e.print();
            exit(if use_stderr { 2 } else { 0 });
        }
    };

    if matches.get_flag("print_manpage") {
        let man = clap_mangen::Man::new(cli::command());
        let mut buf = Vec::<u8>::new();
        clap_mangen::renderer::render(&man, &mut buf).expect("manpage rendering failed");
        print!("{}", String::from_utf8_lossy(&buf));
        return;
    }

    if let Some(shell) = matches.get_one::<String>("print_completions") {
        let mut cmd = cli::command();
        match shell.as_str() {
            "bash" => {
                clap_complete::Shell::Bash.generate(&mut cmd, &mut std::io::stdout());
            }
            "elvish" => {
                clap_complete::Shell::Elvish.generate(&mut cmd, &mut std::io::stdout());
            }
            "fish" => {
                clap_complete::Shell::Fish.generate(&mut cmd, &mut std::io::stdout());
            }
            "powershell" => {
                clap_complete::Shell::PowerShell.generate(&mut cmd, &mut std::io::stdout());
            }
            "zsh" => {
                clap_complete::Shell::Zsh.generate(&mut cmd, &mut std::io::stdout());
            }
            _ => unreachable!(),
        }
        return;
    }

    let cfg = match config::Config::from_matches(&matches) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Error: {}", e);
            exit(1);
        }
    };

    let verbose = matches.get_flag("verbose");
    server::run(cfg, verbose);
}
