pub fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

pub fn days_from_civil(y: i64, m: u32, d: u32) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400;
    let mp = if m > 2 { m - 3 } else { m + 9 } as i64;
    let doy = (153 * mp + 2) / 5 + d as i64 - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

const MONTHS: [&str; 12] = [
    "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
];
const WEEKDAYS: [&str; 7] = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

/// RFC 7231 IMF-fixdate: `Sun, 06 Nov 1994 08:49:37 GMT`
pub fn http_date(secs: i64) -> String {
    let (y, m, d, h, mi, s) = civil_from_epoch(secs);
    let wd = weekday_index(days_from_civil(y, m, d));
    format!(
        "{}, {:02} {} {} {:02}:{:02}:{:02} GMT",
        WEEKDAYS[wd as usize], d, MONTHS[(m - 1) as usize], y, h, mi, s
    )
}

/// Log date: `Wed, 18 Nov 2026 05:51:36 +0000`
pub fn log_date(secs: i64) -> String {
    let (y, m, d, h, mi, s) = civil_from_epoch(secs);
    let wd = weekday_index(days_from_civil(y, m, d));
    format!(
        "{}, {:02} {} {} {:02}:{:02}:{:02} +0000",
        WEEKDAYS[wd as usize], d, MONTHS[(m - 1) as usize], y, h, mi, s
    )
}

/// `2026-11-18 04:51:21 +00:00` (chrono `DateTime<Utc>` display format)
pub fn listing_date(secs: i64) -> String {
    let (y, m, d, h, mi, s) = civil_from_epoch(secs);
    format!(
        "{:04}-{:02}-{:02} {:02}:{:02}:{:02} +00:00",
        y, m, d, h, mi, s
    )
}

fn weekday_index(days: i64) -> u32 {
    (days.rem_euclid(7) + 4) % 7
}

/// Human readable file size, e.g. `12 B`, `1.5 KiB`
pub fn human_size(len: u64) -> String {
    const K: f64 = 1024.0;
    const UNITS: [&str; 8] = [
        "B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB", "ZiB",
    ];
    let mut val = len as f64;
    let mut unit = 0usize;
    while val >= K && unit < UNITS.len() - 1 {
        val /= K;
        unit += 1;
    }
    if unit == 0 {
        format!("{} B", len)
    } else {
        format!("{:.1} {}", val, UNITS[unit])
    }
}

/// Relative ("history") time as displayed by miniserve
pub fn relative_time(diff_secs: i64, now: i64) -> String {
    let s = diff_secs;
    if s <= 10 {
        return "now".to_string();
    }
    if s <= 45 {
        return format!("{} seconds ago", s);
    }
    let (unit, plural, val) = if s <= 2700 {
        ("minute", "minutes", val_of(s, 60))
    } else if s <= 79200 {
        ("hour", "hours", val_of(s, 3600))
    } else if s <= 561600 {
        ("day", "days", val_of(s, 86400))
    } else if s <= 2505600 {
        ("week", "weeks", val_of(s, 604800))
    } else if s <= 29808000 {
        ("month", "months", val_of(s, 2592000))
    } else {
        ("year", "years", val_of(s, 31536000))
    };
    if val <= 1 {
        format!("a {} ago", unit)
    } else {
        format!("{} {} ago", val, plural)
    }
}

fn val_of(secs: i64, unit: i64) -> i64 {
    let f = secs as f64 / unit as f64;
    let fl = f.floor();
    if f > 1.5 && f < 2.0 {
        fl as i64 + 1
    } else {
        fl as i64
    }
}

pub fn relative_time_future(diff_secs: i64) -> String {
    let s = diff_secs;
    if s <= 10 {
        return "now".to_string();
    }
    if s <= 45 {
        return format!("in {} seconds", s);
    }
    let (unit, plural, val) = if s <= 2700 {
        ("minute", "minutes", val_of(s, 60))
    } else if s <= 79200 {
        ("hour", "hours", val_of(s, 3600))
    } else if s <= 561600 {
        ("day", "days", val_of(s, 86400))
    } else if s <= 2505600 {
        ("week", "weeks", val_of(s, 604800))
    } else if s <= 29808000 {
        ("month", "months", val_of(s, 2592000))
    } else {
        ("year", "years", val_of(s, 31536000))
    };
    if val <= 1 {
        format!("in a {}", unit)
    } else {
        format!("in {} {}", val, plural)
    }
}

/// Percent-encode a path component like actix/percent-encoding does (non-alphanumeric
/// and not in the RFC 3986 unreserved/sub-delims set get escaped).
pub fn percent_encode_path(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.as_bytes() {
        let c = *b as char;
        if b.is_ascii_alphanumeric()
            || matches!(b, b'-' | b'_' | b'.' | b'~' | b'!' | b'$' | b'&' | b'\'' | b'(' | b')' | b'*' | b'+' | b',' | b';' | b'=' | b':' | b'@')
        {
            out.push(c);
        } else {
            out.push_str(&format!("%{:02X}", b));
        }
    }
    out
}
