    Error,
    Overwrite,
    Rename,
}

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum MediaType {
    Image,
    Audio,
    Video,
}

#[derive(Clone, PartialEq, Debug)]
pub enum Auth {
    Plain(String, String),
    Sha256(String, Vec<u8>),
    Sha512(String, Vec<u8>),
}

impl Auth {
    pub fn username(&self) -> &str {
        match self {
            Auth::Plain(u, _) | Auth::Sha256(u, _) | Auth::Sha512(u, _) => u,
        }
    }

    pub fn verify(&self, username: &str, password: &str) -> bool {
        if username != self.username() {
            return false;
        }
        match self {
            Auth::Plain(_, p) => p == password,
            Auth::Sha256(_, h) => {
                let mut hasher = crate::sha2::Sha256::new();
                crate::sha2::Digest::update(&mut hasher, password.as_bytes());
                crate::sha2::Digest::finalize(&mut hasher)[..] == h[..]
            }
            Auth::Sha512(_, h) => {
                let mut hasher = crate::sha2::Sha512::new();
                crate::sha2::Digest::update(&mut hasher, password.as_bytes());
                crate::sha2::Digest::finalize(&mut hasher)[..] == h[..]
            }
        }
    }
}

fn hex_decode(s: &str) -> Option<Vec<u8>> {
    if s.len() % 2 != 0 {
        return None;
    }
    let mut out = Vec::with_capacity(s.len() / 2);
    let b = s.as_bytes();
    let mut i = 0;
    while i < b.len() {
        let hi = (b[i] as char).to_digit(16)?;
        let lo = (b[i + 1] as char).to_digit(16)?;
        out.push((hi * 16 + lo) as u8);
        i += 2;
    }
    Some(out)
}

/// Parse a `user:password`, `user:sha256:hash` or `user:sha512:hash` string.
pub fn parse_auth(s: &str) -> Result<Auth, String> {
    let mut split = s.split(':');
    let user = split.next().ok_or_else(|| "no username".to_string())?;
    let second = split.next();
    let third = split.next();
    match (second, third) {
        (None, _) => Err("Invalid format for credentials string. Expected username:password, username:sha256:hash or username:sha512:hash".to_string()),
        (Some(pw), None) => Ok(Auth::Plain(user.to_string(), pw.to_string())),
        (Some(alg), Some(h)) => {
            if alg == "sha256" {
                match hex_decode(h) {
                    Some(v) => Ok(Auth::Sha256(user.to_string(), v)),
                    None => Err("Invalid format for password hash. Expected hex code".to_string()),
                }
            } else if alg == "sha512" {
                match hex_decode(h) {
                    Some(v) => Ok(Auth::Sha512(user.to_string(), v)),
                    None => Err("Invalid format for password hash. Expected hex code".to_string()),
                }
            } else {
                Err("Invalid format for password hash. Expected hex code".to_string())
            }
        }
    }
}

#[derive(Clone)]
pub struct Config {
    pub path: PathBuf,
    pub port: u16,
