    pub disable_indexing: bool,
    pub enable_webdav: bool,
    pub size_display: SizeDisplay,
    pub file_external_url: Option<String>,
    pub verbose: bool,
}

pub fn parse_headers(list: &[String]) -> Vec<(String, String)> {
    list.iter()
