mod render;
mod server;
mod tls;
mod upload;
mod util;
mod webdav;

use std::io::Write;
use std::process::exit;
use std::time::{SystemTime, UNIX_EPOCH};

pub fn now_secs() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0)
}

pub fn log_error(msg: &str) {
    let mut err = std::io::stderr();
    let _ = writeln!(err, "{} [ERROR] {}", util::log_date(now_secs()), msg);
}

pub fn log_info(msg: &str) {
    let mut err = std::io::stderr();
    let _ = writeln!(err, "{} [INFO] {}", util::log_date(now_secs()), msg);
}

pub fn log_warn(msg: &str) {
    let mut err = std::io::stderr();
    let _ = writeln!(err, "{} [WARN] {}", util::log_date(now_secs()), msg);
}

fn main() {
    let matches = match cli::command().try_get_matches_from(std::env::args_os()) {
        Ok(m) => m,
        Err(e) => {
            let use_stderr = e.use_stderr();
            let _ = e.print();
            exit(if use_stderr { 2 } else { 0 });
        }
    };

    if matches.get_flag("print_manpage") {
        let man = clap_mangen::Man::new(cli::command());
        let mut buf = Vec::<u8>::new();
        man.render(&mut buf).expect("manpage rendering failed");
        print!("{}", String::from_utf8_lossy(&buf));
        return;
    }

    if let Some(shell) = matches.get_one::<String>("print_completions") {
        let mut cmd = cli::command();
        match shell.as_str() {
            "bash" => clap_complete::generate(
                clap_complete::Shell::Bash,
                &mut cmd,
                cmd.get_name().to_string(),
                &mut std::io::stdout(),
            ),
            "elvish" => clap_complete::generate(
                clap_complete::Shell::Elvish,
                &mut cmd,
                cmd.get_name().to_string(),
                &mut std::io::stdout(),
            ),
            "fish" => clap_complete::generate(
                clap_complete::Shell::Fish,
                &mut cmd,
                cmd.get_name().to_string(),
                &mut std::io::stdout(),
            ),
            "powershell" => clap_complete::generate(
                clap_complete::Shell::PowerShell,
                &mut cmd,
                cmd.get_name().to_string(),
                &mut std::io::stdout(),
            ),
            "zsh" => clap_complete::generate(
                clap_complete::Shell::Zsh,
                &mut cmd,
                cmd.get_name().to_string(),
                &mut std::io::stdout(),
            ),
            _ => unreachable!(),
        }
        return;
    }

    let verbose = matches.get_flag("verbose");
    let cfg = match config::build_config(&matches, verbose) {
        Ok(c) => c,
        Err(e) => {
            for line in e.split('\n') {
                log_error(line);
            }
            eprintln!("Error: {}", e);
            exit(1);
        }
    };

    server::run(cfg);
}
RUSTEOF
echo ok"}

