/// Build the configuration from the parsed command line arguments.
pub fn build_config(
    m: &clap::ArgMatches,
    verbose: bool,
) -> Result<Config, String> {
    let port: u16 = *m
        .get_one("port")
        .ok_or_else(|| "missing port".to_string())?;

    let interfaces: Vec<String> = m
        .get_many::<String>("interfaces")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();

    let mut auth: Vec<Auth> = Vec::new();
    if let Some(vals) = m.get_many::<String>("auth") {
        for v in vals {
            match parse_auth(v) {
                Ok(a) => auth.push(a),
                Err(e) => return Err(format!("Invalid auth: {}", e)),
            }
        }
    }

    let header: Vec<(String, String)> = parse_headers(
        &m.get_many::<String>("header")
            .map(|v| v.cloned().collect())
            .unwrap_or_default(),
    );

    let media_type = match m.get_one::<String>("media_type").map(|s| s.as_str()) {
        Some("image") => Some(MediaType::Image),
        Some("audio") => Some(MediaType::Audio),
        Some("video") => Some(MediaType::Video),
        _ => None,
    };

    let on_duplicate_files = match m
        .get_one::<String>("on_duplicate_files")
        .map(|s| s.as_str())
        .unwrap_or("error")
    {
        "overwrite" => OnDuplicate::Overwrite,
        "rename" => OnDuplicate::Rename,
        _ => OnDuplicate::Error,
    };

    let size_display = match m
        .get_one::<String>("size_display")
        .map(|s| s.as_str())
        .unwrap_or("human")
    {
        "exact" => SizeDisplay::Exact,
        _ => SizeDisplay::Human,
    };

    let default_sorting_method = match m
        .get_one::<String>("default_sorting_method")
        .map(|s| s.as_str())
        .unwrap_or("name")
    {
        "size" => SortMethod::Size,
        "date" => SortMethod::Date,
        _ => SortMethod::Name,
    };

    let default_sorting_order = match m
        .get_one::<String>("default_sorting_order")
        .map(|s| s.as_str())
        .unwrap_or("desc")
    {
        "asc" => SortOrder::Asc,
        _ => SortOrder::Desc,
    };

    let upload_files = if let Some(v) = m.get_one::<String>("upload_files") {
        Some(Some(PathBuf::from(v)))
    } else if m.get_flag("upload_files_present") || m.contains_id("upload_files") {
        Some(None)
    } else {
        None
    };

    let rm_files = if let Some(v) = m.get_one::<String>("rm_files") {
        Some(Some(PathBuf::from(v)))
    } else {
        None
    };

    let chmod: Option<u32> = match m.get_one::<String>("chmod") {
        Some(v) => match u32::from_str_radix(v, 8) {
            Ok(n) => Some(n),
            Err(e) => return Err(format!("Invalid chmod value: {}", e)),
        },
        None => None,
    };

    let path = match m.get_one::<String>("path") {
        Some(p) => {
            let pb = std::path::Path::new(p);
            match pb.canonicalize() {
                Ok(c) => c,
                Err(e) => {
                    return Err(format!(
                        "Failed to resolve path to be served\ncaused by: {}",
                        e
                    ))
                }
            }
        }
        None => {
            if !crate::is_tty() {
                return Err("Refusing to start as no explicit serve path was set and no interactive terminal was attached\nPlease set an explicit serve path like: `miniserve /my/path`".to_string());
            }
            match std::env::current_dir() {
                Ok(c) => c,
                Err(e) => {
                    return Err(format!(
                        "Failed to resolve path to be served\ncaused by: {}",
                        e
                    ))
                }
            }
        }
    };

    let mut route_prefix = m.get_one::<String>("route_prefix").map(|s| s.to_string());
    if m.get_flag("random_route") {
        if route_prefix.is_some() {
            return Err("Cannot use both --route-prefix and --random-route".to_string());
        }
        let mut buf = [0u8; 3];
        crate::rand_bytes(&mut buf);
        route_prefix = Some(format!("{:02x}{:02x}{:02x}", buf[0], buf[1], buf[2]));
    }

    Ok(Config {
        path,
        port,
        interfaces,
        auth,
        auth_file: m.get_one::<String>("auth_file").map(PathBuf::from),
        route_prefix,
        no_symlinks: m.get_flag("no_symlinks"),
        hidden: m.get_flag("hidden"),
        default_sorting_method,
        default_sorting_order,
        color_scheme: m
            .get_one::<String>("color_scheme")
            .map(|s| s.to_string())
            .unwrap_or_else(|| "squirrel".to_string()),
        color_scheme_dark: m
            .get_one::<String>("color_scheme_dark")
            .map(|s| s.to_string())
            .unwrap_or_else(|| "archlinux".to_string()),
        qrcode: m.get_flag("qrcode"),
        upload_files,
        web_upload_files_concurrency: m
            .get_one::<usize>("web_upload_files_concurrency")
            .copied()
            .unwrap_or(0),
        chmod,
        directory_size: m.get_flag("directory_size"),
        mkdir_enabled: m.get_flag("mkdir_enabled"),
        media_type,
        raw_media_type: m.get_one::<String>("raw_media_type").map(|s| s.to_string()),
        on_duplicate_files,
        rm_files,
        enable_tar: m.get_flag("enable_tar"),
        enable_tar_gz: m.get_flag("enable_tar_gz"),
        enable_zip: m.get_flag("enable_zip"),
        compress_response: m.get_flag("compress_response"),
        dirs_first: m.get_flag("dirs_first"),
        title: m.get_one::<String>("title").map(|s| s.to_string()),
        header,
        show_symlink_info: m.get_flag("show_symlink_info"),
        hide_version_footer: m.get_flag("hide_version_footer"),
        hide_theme_selector: m.get_flag("hide_theme_selector"),
        show_wget_footer: m.get_flag("show_wget_footer"),
        tls_cert: m.get_one::<String>("tls_cert").map(PathBuf::from),
        tls_key: m.get_one::<String>("tls_key").map(PathBuf::from),
        readme: m.get_flag("readme"),
        disable_indexing: m.get_flag("disable_indexing"),
        enable_webdav: m.get_flag("enable_webdav"),
        size_display,
        file_external_url: m.get_one::<String>("file_external_url").map(|s| s.to_string()),
        verbose,
    })
}
RUSTEOF
echo ok"}

