{"command": "cd /workspace && cat > src/http.rs <<'RUSTEOF'
use std::io::{Read, Write};

pub struct Request {
    pub method: String,
    pub target: String,
    pub path: String,
    pub query: String,
    pub version: String,
    pub headers: Vec<(String, String)>,
    pub body: Vec<u8>,
    pub remote_ip: String,
    pub keep_alive: bool,
}

impl Request {
    pub fn header(&self, name: &str) -> Option<&str> {
        self.headers
            .iter()
            .find(|(k, _)| k == name)
            .map(|(_, v)| v.as_str())
    }
}

pub enum Body {
    Full(Vec<u8>),
    /// Streamed with chunked transfer encoding
    Stream(Box<dyn Fn(&mut dyn Write) -> std::io::Result<()> + Send>),
}

pub struct Response {
    pub status: u16,
    pub headers: Vec<(String, String)>,
    pub body: Body,
    pub no_length: bool,
}

impl Response {
    pub fn text(status: u16, content_type: &str, body: String) -> Response {
        Response {
            status,
            headers: vec![("content-type".into(), content_type.into())],
            body: Body::Full(body.into_bytes()),
            no_length: false,
        }
    }

    pub fn status_text(status: u16) -> &'static str {
        match status {
            200 => "OK",
            201 => "Created",
            204 => "No Content",
            206 => "Partial Content",
            207 => "Multi-Status",
            301 => "Moved Permanently",
            302 => "Found",
            304 => "Not Modified",
            400 => "Bad Request",
            401 => "Unauthorized",
            403 => "Forbidden",
            404 => "Not Found",
            405 => "Method Not Allowed",
            409 => "Conflict",
            413 => "Payload Too Large",
            415 => "Unsupported Media Type",
            416 => "Range Not Satisfiable",
            418 => "I'm a teapot",
            500 => "Internal Server Error",
            501 => "Not Implemented",
            _ => "Unknown",
        }
    }
}

pub enum Conn {
    Plain(std::net::TcpStream),
    Tls(crate::tls::TlsStream),
}

impl Conn {
    pub fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
        match self {
            Conn::Plain(s) => s.read(buf),
            Conn::Tls(s) => s.read(buf),
        }
    }

    pub fn write_all(&mut self, buf: &[u8]) -> std::io::Result<()> {
        match self {
            Conn::Plain(s) => s.write_all(buf),
            Conn::Tls(s) => s.write_all(buf),
        }
    }

    pub fn flush(&mut self) -> std::io::Result<()> {
        match self {
            Conn::Plain(s) => s.flush(),
            Conn::Tls(s) => s.flush(),
        }
    }

    pub fn shutdown(&mut self) -> std::io::Result<()> {
        match self {
            Conn::Plain(s) => s.shutdown(std::net::Shutdown::Write),
            Conn::Tls(s) => s.close(),
        }
    }
}

/// Parse a single percent-encoded path into its raw percent-encoded form (kept as-is)
/// and a decoded version.
pub fn url_decode(s: &str) -> String {
    let bytes = s.as_bytes();
    let mut out: Vec<u8> = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%' && i + 2 < bytes.len() {
            let hi = (bytes[i + 1] as char).to_digit(16);
            let lo = (bytes[i + 2] as char).to_digit(16);
            if let (Some(h), Some(l)) = (hi, lo) {
                out.push((h * 16 + l) as u8);
                i += 3;
                continue;
            }
        }
        out.push(bytes[i]);
        i += 1;
    }
    String::from_utf_lossy(&out).to_string()
}

/// Read a full HTTP request from the connection.
pub fn read_request(conn: &mut Conn, remote_ip: &str) -> std::io::Result<Option<Request>> {
    let mut buf: Vec<u8> = Vec::with_capacity(1024);
    let mut tmp = [0u8; 8192];
    // read until the end of headers
    let header_end;
    loop {
        if let Some(pos) = find_header_end(&buf) {
            header_end = pos;
            break;
        }
        if buf.len() > 65536 {
            return Ok(None);
        }
        let n = conn.read(&mut tmp)?;
        if n == 0 {
            if buf.is_empty() {
                return Ok(None);
            }
            return Ok(None);
        }
        buf.extend_from_slice(&tmp[..n]);
    }
    let head = String::from_utf_lossy(&buf[..header_end]).to_string();
    let mut lines = head.split("\r\n");
    let request_line = lines.next().unwrap_or("");
    let mut parts = request_line.split(' ');
    let method = parts.next().unwrap_or("").to_string();
    let target = parts.next().unwrap_or("").to_string();
    let version = parts.next().unwrap_or("").to_string();
    let mut headers: Vec<(String, String)> = Vec::new();
    for line in lines {
        if line.is_empty() {
            continue;
        }
        if let Some(idx) = line.find(':') {
            let name = line[..idx].trim().to_lowercase();
            let value = line[idx + 1..].trim().to_string();
            headers.push((name, value));
        }
    }
    let content_length = headers
        .iter()
        .find(|(k, _)| k == "content-length")
        .and_then(|(_, v)| v.parse::<usize>().ok())
        .unwrap_or(0);
    let mut body = buf[header_end + 4..].to_vec();
    while body.len() < content_length {
        let n = conn.read(&mut tmp)?;
        if n == 0 {
            break;
        }
        body.extend_from_slice(&tmp[..n]);
    }
    if body.len() > content_length {
        // extra data is not expected for our simple usage
    }
    body.truncate(content_length);

    let keep_alive = match headers.iter().find(|(k, _)| k == "connection") {
        Some((_, v)) if v.eq_ignore_ascii_case("close") => false,
        Some((_, v)) if v.eq_ignore_ascii_case("keep-alive") => true,
        _ => version == "HTTP/1.1",
    };

    let (path_raw, query) = match target.find('?') {
        Some(idx) => (target[..idx].to_string(), target[idx + 1..].to_string()),
        None => (target.clone(), String::new()),
    };
    let path = url_decode(&path_raw);

    Ok(Some(Request {
        method,
        target,
        path,
        query,
        version,
        headers,
        body,
        remote_ip: remote_ip.to_string(),
        keep_alive,
    }))
}

fn find_header_end(buf: &[u8]) -> Option<usize> {
    buf.windows(4).position(|w| w == b"\r\n\r\n")
}

/// Write a response to the connection.
pub fn write_response(conn: &mut Conn, resp: &Response, keep_alive: bool) -> std::io::Result<()> {
    let mut head = format!("HTTP/1.1 {} {}\r\n", resp.status, Response::status_text(resp.status));
    let mut chunked = false;
    match &resp.body {
        Body::Full(b) => {
            if !resp.no_length {
                head.push_str(&format!("content-length: {}\r\n", b.len()));
            }
        }
        Body::Stream(_) => {
            chunked = true;
            head.push_str("transfer-encoding: chunked\r\n");
        }
    }
    for (k, v) in &resp.headers {
        head.push_str(&format!("{}: {}\r\n", k, v));
    }
    head.push_str(&format!(
        "date: {}\r\n",
        crate::util::http_date(crate::now_secs())
    ));
    if keep_alive {
        head.push_str("connection: keep-alive\r\n");
    } else {
        head.push_str("connection: close\r\n");
    }
    head.push_str("\r\n");
    conn.write_all(head.as_bytes())?;
    match &resp.body {
        Body::Full(b) => conn.write_all(b)?,
        Body::Stream(f) => {
            let mut sink = ChunkSink { conn, started: false };
            f(&mut sink)?;
            if !sink.started {
                sink.conn.write_all(b"0\r\n\r\n")?;
            } else {
                sink.conn.write_all(b"\r\n0\r\n\r\n")?;
            }
        }
    }
    conn.flush()?;
    Ok(())
}

struct ChunkSink<'a> {
    conn: &'a mut Conn,
    started: bool,
}

impl<'a> Write for ChunkSink<'a> {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        if buf.is_empty() {
            return Ok(0);
        }
        if self.started {
            self.conn.write_all(b"\r\n")?;
        }
        self.started = true;
        self.conn
            .write_all(format!("{:x}\r\n", buf.len()).as_bytes())?;
        self.conn.write_all(buf)?;
        Ok(buf.len())
    }
    fn flush(&mut self) -> std::io::Result<()> {
        self.conn.flush()
    }
}
RUSTEOF
