//! Minimal TLS support through OpenSSL (libssl).
#![allow(non_camel_case_types, dead_code)]

use std::os::raw::{c_char, c_int, c_long, c_void};

pub type size_t = usize;

#[repr(C)]
pub struct SSL_CTX {
    _private: [u8; 0],
}
#[repr(C)]
pub struct SSL {
    _private: [u8; 0],
}
#[repr(C)]
pub struct BIO {
    _private: [u8; 0],
}

extern "C" {
    fn TLS_server_method() -> *const c_void;
    fn SSL_CTX_new(m: *const c_void) -> *mut SSL_CTX;
    fn SSL_CTX_free(ctx: *mut SSL_CTX);
    fn SSL_new(ctx: *mut SSL_CTX) -> *mut SSL;
    fn SSL_free(ssl: *mut SSL);
    fn SSL_set_fd(ssl: *mut SSL, fd: c_int) -> c_int;
    fn SSL_accept(ssl: *mut SSL) -> c_int;
    fn SSL_read(ssl: *mut SSL, buf: *mut c_void, num: c_int) -> c_int;
    fn SSL_write(ssl: *mut SSL, buf: *const c_void, num: c_int) -> c_int;
    fn SSL_shutdown(ssl: *mut SSL) -> c_int;
    fn SSL_get_error(ssl: *mut SSL, ret: c_int) -> c_int;
    fn SSL_CTX_use_certificate_chain_file(ctx: *mut SSL_CTX, file: *const c_char) -> c_int;
    fn SSL_CTX_use_PrivateKey_file(
        ctx: *mut SSL_CTX,
        file: *const c_char,
        typ: c_int,
    ) -> c_int;
    fn SSL_CTX_ctrl(ctx: *mut SSL_CTX, cmd: c_int, larg: c_long, parg: *mut c_void) -> c_long;
    fn SSL_get_current_cipher(ssl: *mut SSL) -> *mut c_void;
    fn SSL_CTX_set_options(ctx: *mut SSL_CTX, op: u64) -> u64;
    fn SSL_set_accept_state(ssl: *mut SSL);
}

const SSL_FILETYPE_PEM: c_int = 1;
const SSL_ERROR_WANT_READ: c_int = 2;
const SSL_ERROR_WANT_WRITE: c_int = 3;
const SSL_ERROR_SYSCALL: c_int = 5;
const SSL_ERROR_ZERO_RETURN: c_int = 6;

pub struct TlsCtx {
    ctx: *mut SSL_CTX,
}

impl TlsCtx {
    pub fn new(cert: &str, key: &str) -> Result<TlsCtx, String> {
        unsafe {
            let method = TLS_server_method();
            let ctx = SSL_CTX_new(method);
            if ctx.is_null() {
                return Err("Failed to create TLS context".into());
            }
            let cert_c = std::ffi::CString::new(cert).unwrap();
            let key_c = std::ffi::CString::new(key).unwrap();
            if SSL_CTX_use_certificate_chain_file(ctx, cert_c.as_ptr()) != 1 {
                SSL_CTX_free(ctx);
                return Err(format!("No certificate found"));
            }
            if SSL_CTX_use_PrivateKey_file(ctx, key_c.as_ptr(), SSL_FILETYPE_PEM) != 1 {
                SSL_CTX_free(ctx);
                return Err("No private key found".into());
            }
            Ok(TlsCtx { ctx })
        }
    }

    pub fn accept(&self, fd: c_int) -> Result<TlsStream, std::io::Error> {
        unsafe {
            let ssl = SSL_new(self.ctx);
            if ssl.is_null() {
                return Err(std::io::Error::new(
                    std::io::ErrorKind::Other,
                    "SSL_new failed",
                ));
            }
            SSL_set_fd(ssl, fd);
            SSL_set_accept_state(ssl);
            let mut ret = SSL_accept(ssl);
            let mut tries = 0;
            while ret != 1 {
                let err = SSL_get_error(ssl, ret);
                if err == SSL_ERROR_WANT_READ || err == SSL_ERROR_WANT_WRITE {
                    std::thread::sleep(std::time::Duration::from_millis(1));
                    ret = SSL_accept(ssl);
                    tries += 1;
                    if tries > 1000 {
                        break;
                    }
                    continue;
                }
                SSL_free(ssl);
                return Err(std::io::Error::new(
                    std::io::ErrorKind::Other,
                    "TLS handshake failed",
                ));
            }
            Ok(TlsStream { ssl })
        }
    }
}

impl Drop for TlsCtx {
    fn drop(&mut self) {
        unsafe {
            if !self.ctx.is_null() {
                SSL_CTX_free(self.ctx);
            }
        }
    }
}

unsafe impl Send for TlsCtx {}
unsafe impl Sync for TlsCtx {}

pub struct TlsStream {
    ssl: *mut SSL,
}

impl TlsStream {
    pub fn close(&mut self) -> std::io::Result<()> {
        unsafe {
            SSL_shutdown(self.ssl);
            SSL_free(self.ssl);
            self.ssl = std::ptr::null_mut();
        }
        Ok(())
    }
}

impl Read for TlsStream {
    fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
        unsafe {
            if self.ssl.is_null() {
                return Ok(0);
            }
            let n = SSL_read(self.ssl, buf.as_mut_ptr() as *mut c_void, buf.len() as c_int);
            if n > 0 {
                return Ok(n as usize);
            }
            let err = SSL_get_error(self.ssl, n);
            if err == SSL_ERROR_WANT_READ || err == SSL_ERROR_WANT_WRITE {
                return Err(std::io::Error::new(std::io::ErrorKind::WouldBlock, "want"));
            }
            if err == SSL_ERROR_ZERO_RETURN {
                return Ok(0);
            }
            Ok(0)
        }
    }
}

impl Write for TlsStream {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        unsafe {
            let mut written = 0usize;
            while written < buf.len() {
                let n = SSL_write(
                    self.ssl,
                    buf[written..].as_ptr() as *const c_void,
                    (buf.len() - written) as c_int,
                );
                if n > 0 {
                    written += n as usize;
                } else {
                    let err = SSL_get_error(self.ssl, n);
                    if err == SSL_ERROR_WANT_READ || err == SSL_ERROR_WANT_WRITE {
                        continue;
                    }
                    if written == 0 {
                        return Err(std::io::Error::new(
                            std::io::ErrorKind::Other,
                            "SSL write failed",
                        ));
                    }
                    break;
                }
            }
            Ok(written)
        }
    }
    fn flush(&mut self) -> std::io::Result<()> {
        Ok(())
    }
}

impl Drop for TlsStream {
    fn drop(&mut self) {
        unsafe {
            if !self.ssl.is_null() {
                SSL_shutdown(self.ssl);
                SSL_free(self.ssl);
            }
        }
    }
}

unsafe impl Send for TlsStream {}
RUSTEOF
