use crate::config::Config;
use crate::http::{Body, Conn, Request, Response};
use std::io::Write;
use std::net::{IpAddr, SocketAddr, TcpListener, TcpStream};
use std::sync::Arc;

/// Resolved serve information shared by all request handlers.
pub struct ServeState {
    pub cfg: Config,
    pub tls: Option<Arc<crate::tls::TlsCtx>>,
    pub route_prefix: String,
    pub host: String,
}

pub fn run(cfg: crate::config::Config) {
    let tls = match (&cfg.tls_cert, &cfg.tls_key) {
        (Some(cert), Some(key)) => match crate::tls::TlsCtx::new(
            &cert.to_string_lossy(),
            &key.to_string_lossy(),
        ) {
            Ok(c) => Some(Arc::new(c)),
            Err(e) => {
                crate::log_error(&format!("TLS setup failed: {}", e));
                std::process::exit(1);
            }
        },
        (Some(_), None) | (None, Some(_)) => {
            crate::log_error("TLS certificate and key must be provided together");
            std::process::exit(1);
        }
        _ => None,
    };

    let route_prefix = cfg.route_prefix.clone().unwrap_or_default();

    let addrs: Vec<IpAddr> = if cfg.interfaces.is_empty() {
        vec![IpAddr::from([0, 0, 0, 0, 0, 0, 0, 0]), IpAddr::from([0, 0, 0, 0])]
    } else {
        cfg.interfaces
            .iter()
            .map(|i| i.parse::<IpAddr>().unwrap())
            .collect()
    };

    let mut listeners: Vec<(IpAddr, TcpListener)> = Vec::new();
    for a in &addrs {
        let sa = SocketAddr::new(*a, cfg.port);
        match TcpListener::bind(sa) {
            Ok(l) => listeners.push((*a, l)),
            Err(e) => {
                crate::log_error(&format!(
                    "Failed to bind server to {}",
                    display_addr(sa)
                ));
                crate::log_error(&format!("caused by: {}", e));
                eprintln!("Error: Failed to bind server to {}", display_addr(sa));
                eprintln!("caused by: {}", e);
                std::process::exit(1);
            }
        }
    }

    // Startup banner
    println!("miniserve v{}", crate::cli::VERSION);
    let bound: Vec<String> = listeners
        .iter()
        .map(|(a, _)| display_addr(SocketAddr::new(*a, cfg.port)))
        .collect();
    println!("Bound to {}", bound.join(", "));
    println!("Serving path {}", cfg.path.display());
    let urls: Vec<String> = addrs.iter().map(|a| format!("    {}", display_url(*a, cfg.port))).collect();
    println!("Available at (non-exhaustive list):");
    for u in urls {
        println!("{}", u);
    }
    println!();

    if cfg.verbose {
        crate::log_info(&format!("starting {} workers", crate::worker_count()));
        crate::log_info("Actix runtime found; starting in Actix runtime");
        for (a, _) in &listeners {
            crate::log_info(&format!(
                "starting service: \"actix-web-service-{}\", workers: {}, listening on: {}",
                display_addr(SocketAddr::new(*a, cfg.port)),
                crate::worker_count(),
                display_addr(SocketAddr::new(*a, cfg.port))
            ));
        }
    }

    let state = Arc::new(ServeState {
        cfg,
        tls,
        route_prefix,
        host: String::new(),
    });

    let mut threads = Vec::new();
    for (a, l) in listeners {
        let st = state.clone();
        threads.push(std::thread::spawn(move || {
            for stream in l.incoming() {
                match stream {
                    Ok(s) => {
                        let st2 = st.clone();
                        std::thread::spawn(move || {
                            handle_connection(s, &st2, a.is_ipv6());
                        });
                    }
                    Err(_) => continue,
                }
            }
        }));
    }
    for t in threads {
        let _ = t.join();
    }
}

fn display_addr(sa: SocketAddr) -> String {
    match sa.ip() {
        IpAddr::V4(v) => format!("{}:{}", v, sa.port()),
        IpAddr::V6(v) => format!("[{}]:{}", v, sa.port()),
    }
}

fn display_url(ip: IpAddr, port: u16) -> String {
    match ip {
        IpAddr::V4(v) => {
            if v.is_unspecified() {
                format!("http://127.0.0.1:{}", port)
            } else {
                format!("http://{}:{}", v, port)
            }
        }
        IpAddr::V6(v) => {
            if v.is_unspecified() {
                format!("http://[::1]:{}", port)
            } else {
                format!("http://[{}]:{}", v, port)
            }
        }
    }
}

fn handle_connection(stream: TcpStream, state: &Arc<ServeState>, _v6: bool) {
    let remote_ip = match stream.peer_addr() {
        Ok(a) => a.ip().to_string(),
        Err(_) => "0.0.0.0".to_string(),
    };
    let _ = stream.set_nodelay(true);
    let _ = stream.set_read_timeout(Some(std::time::Duration::from_secs(30)));

    let tls_stream = match &state.tls {
        Some(ctx) => match ctx.accept(stream.as_raw_fd()) {
            Ok(s) => Some(s),
            Err(_) => return,
        },
        None => None,
    };

    let mut conn = match tls_stream {
        Some(s) => Conn::Tls(s),
        None => Conn::Plain(stream),
    };

    loop {
        let req = match crate::http::read_request(&mut conn, &remote_ip) {
            Ok(Some(r)) => r,
            _ => break,
        };
        let keep_alive = req.keep_alive;
        let resp = crate::handler::handle(req, state);
        if crate::http::write_response(&mut conn, &resp, keep_alive).is_err() {
            break;
        }
        if !keep_alive {
            break;
        }
    }
    let _ = conn.shutdown();
}
RUSTEOF
echo ok"}

