    out.push_str("</ul></div>");
    out
}

/// Column / mobile-info sort link helper.
struct SortLink {
    active: bool,
    chevron: &'static str,
    order: &'static str,
    title_dir: &'static str,
}

fn sort_link_for(col: &str, active_sort: &Option<SortMethod>, active_order: SortOrder) -> SortLink {
    let is_active = match active_sort {
        Some(SortMethod::Name) => col == "name",
        Some(SortMethod::Size) => col == "size",
        Some(SortMethod::Date) => col == "date",
        None => false,
    };
    if is_active {
        match active_order {
            SortOrder::Asc => SortLink {
                active: true,
                chevron: "\u{25B4}",
                order: "desc",
                title_dir: "descending",
            },
            SortOrder::Desc => SortLink {
                active: true,
                chevron: "\u{25BE}",
                order: "asc",
                title_dir: "ascending",
            },
        }
    } else {
        SortLink {
            active: false,
            chevron: "\u{25BE}",
            order: "asc",
            title_dir: "ascending",
        }
    }
}

impl SortLink {
    fn span_open(&self) -> &'static str {
        if self.active {
            "<span class=\"active\">"
        } else {
            "<span class=\"\">"
        }
    }
}

pub struct ListingContext<'a> {
    pub state: &'a ServeState,
    pub req: &'a Request,
    pub rel_path: &'a str,
    pub sort: Option<SortMethod>,
    pub order: SortOrder,
    pub active_sort: Option<SortMethod>,
    pub active_order: SortOrder,
    pub url_prefix: String,
    pub page_title: String,
    pub entries: Vec<Entry>,
    pub readme: Option<String>,
    pub readme_name: Option<String>,
    pub depth: usize,
}

pub fn render_listing(ctx: &ListingContext) -> String {
    let c = &ctx.state.cfg;
    let base = format!("/{}", ctx.url_prefix);
    let favicon = format!("{}__miniserve_internal/favicon.svg", base);
    let style = format!("{}__miniserve_internal/style.css", base);

    let mut out = String::with_capacity(4096 + ctx.entries.len() * 300);
    out.push_str(include_str!("../assets/tpl/head_prefix.part"));
    out.push_str(&html_escape(&ctx.page_title));
    out.push_str("</title>");
    out.push_str(include_str!("../assets/tpl/scheme.part"));
    out.push_str(include_str!("../assets/tpl/api.part"));
    if c.upload_files.is_some() {
        let script = include_str!("../assets/tpl/upload.part");
        out.push_str(&script.replace("const CONCURRENCY = 0;", &format!("const CONCURRENCY = {};", c.web_upload_files_concurrency)));
    }
    out.push_str("</head><body id=\"drop-container\"><div class=\"toolbar_box_group\">");
    if c.upload_files.is_some() {
        out.push_str("<div class=\"drag-form\"><div class=\"form_title\"><h1>Drop your file here to upload it</h1></div></div>");
    }
    out.push_str("</div><nav>");
    if c.qrcode {
        let url = format!(
            "{}://{}{}",
            if ctx.state.tls.is_some() { "https" } else { "http" },
            ctx.req.header("host").unwrap_or(""),
            ctx.req.target
        );
        let (n, path) = crate::qr::qr_svg(&url);
        out.push_str(&format!("<div><p>QR code</p><div class=\"qrcode\" id=\"qrcode\" title=\"{url}\"><svg viewBox=\"0 0 {n} {n}\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"{n}px\" height=\"{n}px\" fill=\"#ffffff\"/><path d=\"{path}\" fill=\"#000000\"/></svg></div></div>", url=html_escape(&url), n=n, path=path));
    }
    out.push_str(&theme_nav(c));
    out.push_str("</nav><div class=\"container\"><span id=\"top\"></span><h1 class=\"title\" dir=\"ltr\">");
    // breadcrumb
    out.push_str(&format!("<a href=\"/\"><bdi>{}</bdi></a>", html_escape(&ctx.page_title)));
    for part in ctx.rel_path.split('/').filter(|p| !p.is_empty()) {
        out.push_str(&format!(
            "/<span><bdi>{}</bdi></span>",
            html_escape(part)
        ));
    }
    out.push_str("/");
    out.push_str("</h1><div class=\"toolbar\">");
    if c.enable_zip {
        out.push_str("<div class=\"download\"><a href=\"?download=zip\">Download .zip</a></div>");
    }
    if c.enable_tar {
        out.push_str("<div class=\"download\"><a href=\"?download=tar\">Download .tar</a></div>");
    }
    if c.enable_tar_gz {
        out.push_str("<div class=\"download\"><a href=\"?download=tar_gz\">Download .tar.gz</a></div>");
    }
    out.push_str("<div class=\"toolbar_box_group\">");
    if let Some(upload_dir) = &c.upload_files {
        let up_path = match upload_dir {
            Some(d) => format!("/{}", crate::util::percent_encode_path(&d.to_string_lossy())),
            None => String::new(),
        };
        out.push_str(&format!(
            "<div class=\"toolbar_box\"><form id=\"file_submit\" action=\"{}/upload?path=/\" method=\"POST\" enctype=\"multipart/form-data\"><p>Select a file to upload or drag it anywhere into the window</p><div><input id=\"file-input\" type=\"file\" name=\"file_to_upload\" required=\"\" multiple></input><button type=\"submit\">Upload file</button></div></form></div>",
            base
        ));
        let _ = up_path;
    }
    if c.mkdir_enabled {
        out.push_str("<div class=\"toolbar_box\"><form id=\"mkdir\" action=\"/upload?path=/\" method=\"POST\" enctype=\"multipart/form-data\"><p>Specify a directory name to create</p><div class=\"toolbar_box\"><input type=\"text\" name=\"mkdir\" required=\"\" placeholder=\"Directory name\"></input><button type=\"submit\">Create directory</button></div></form></div>");
    }
    out.push_str("</div></div><table>");
    // thead
    let name_l = sort_link_for("name", &ctx.active_sort, ctx.active_order);
    let size_l = sort_link_for("size", &ctx.active_sort, ctx.active_order);
    let date_l = sort_link_for("date", &ctx.active_sort, ctx.active_order);
    out.push_str(&format!(
        "<thead><th class=\"name\">{sp}<span class=\"chevron\">{ch}</span><a href=\"?sort=name&amp;order={o}\" title=\"Sort by name in {d} order\">Name</a></span></th><th class=\"size\">{sp2}<span class=\"chevron\">{ch2}</span><a href=\"?sort=size&amp;order={o2}\" title=\"Sort by size in {d2} order\">Size</a></span></th><th class=\"date\">{sp3}<span class=\"chevron\">{ch3}</span><a href=\"?sort=date&amp;order={o3}\" title=\"Sort by date in {d3} order\">Last modification</a></span></th>{actions}</thead>",
        sp = name_l.span_open(), ch = name_l.chevron, o = name_l.order, d = name_l.title_dir,
        sp2 = size_l.span_open(), ch2 = size_l.chevron, o2 = size_l.order, d2 = size_l.title_dir,
        sp3 = date_l.span_open(), ch3 = date_l.chevron, o3 = date_l.order, d3 = date_l.title_dir,
        actions = if c.rm_files.is_some() { "<th class=\"actions\"><span>Actions</span></th>" } else { "" }
    ));
    out.push_str("<tbody>");
    for e in &ctx.entries {
        render_row(&mut out, ctx, e);
    }
    out.push_str("</tbody></table>");
    if let (Some(r), Some(n)) = (&ctx.readme, &ctx.readme_name) {
        out.push_str(&format!("<div id=\"readme\"><h3 id=\"readme-filename\">{}</h3><div id=\"readme-contents\">{}</div></div>", html_escape(n), r));
    }
    out.push_str("<a class=\"back\" href=\"#top\">⇪</a><div class=\"footer\">");
    if c.show_wget_footer {
        out.push_str(&wget_footer(ctx));
    }
    if !c.hide_version_footer {
        out.push_str(&format!("<div class=\"version\">{}</div>", VERSION_LINK));
    }
    out.push_str("</div></div>");
    out.push_str(include_str!("../assets/tpl/upload_area.part"));
    out.push_str("</body></html>");
    out
}

fn wget_footer(ctx: &ListingContext) -> String {
    let c = &ctx.state.cfg;
    let host = ctx.req.header("host").unwrap_or("").to_string();
    let title = c.title.clone().unwrap_or_else(|| host.clone());
    let mut opts = String::new();
    if c.file_external_url.is_some() {
        opts.push_str("-H ");
    } else {
        opts.push_str("-nH ");
    }
    if ctx.depth == 0 {
        opts.push_str(&format!("-P '{}' ", html_escape(&title)));
    } else if ctx.depth >= 2 {
        opts.push_str(&format!("--cut-dirs={} ", ctx.depth - 1));
    }
    let url = format!(
        "http://{}{}?raw=true",
        host,
        crate::util::percent_encode_path(&ctx.req.path)
    );
    format!(
        "<div class=\"downloadDirectory\"><p>Download folder:</p><a class=\"cmd\" title=\"Click to copy!\" style=\"cursor: pointer;\" onclick=\"navigator.clipboard.writeText(&quot;wget -rcnp -R 'index.html*' {opts}'{url}'&quot;)\">wget -rcnp -R 'index.html*' {opts}'{url}'</a></div>",
        opts = opts,
        url = html_escape(&url)
    )
}

fn render_row(out: &mut String, ctx: &ListingContext, e: &Entry) {
    let c = &ctx.state.cfg;
    let size_str = match c.size_display {
        SizeDisplay::Exact => format!("{} B", e.size),
        SizeDisplay::Human => crate::util::human_size(e.size),
    };
    let date_str = crate::util::listing_date(e.mtime);
    let hist = if e.mtime > crate::now_secs() {
        crate::util::relative_time_future(e.mtime - crate::now_secs())
    } else {
        crate::util::relative_time(crate::now_secs() - e.mtime, crate::now_secs())
    };
    let href = format!("{}{}", ctx.url_prefix, crate::util::percent_encode_path(&e.name));
    let href = if e.is_dir {
        if let (Some(s), Some(o)) = (&ctx.active_sort, Some(&ctx.active_order)) {
            let sv = match s {
                SortMethod::Name => "name",
                SortMethod::Size => "size",
                SortMethod::Date => "date",
            };
            let ov = match o {
                SortOrder::Asc => "asc",
                SortOrder::Desc => "desc",
            };
            format!("/{}/?sort={}&order={}", crate::util::percent_encode_path(&href), sv, ov)
        } else {
            format!("/{}/", crate::util::percent_encode_path(&href))
        }
    } else if let Some(ext) = &c.file_external_url {
        format!("{}{}", ext, crate::util::percent_encode_path(&href))
    } else {
        format!("/{}", crate::util::percent_encode_path(&href))
    };
    let name_display = if e.is_dir {
        format!("{}", e.name)
    } else {
        e.name.clone()
    };
    let cls = if e.is_symlink && c.show_symlink_info {
        "symlink"
    } else if e.is_dir {
        "directory"
    } else {
        "file"
    };
    let name_link = format!(
        "<a class=\"{}\" href=\"{}\">{}</a>",
        cls,
        html_escape(&href),
        html_escape(&format!("{}{}", e.name, if e.is_dir { "/" } else { "" }))
    );
    let name_cell = if e.is_symlink && c.show_symlink_info {
        let inner_cls = if e.is_dir { "directory" } else { "file" };
        let inner = if e.is_dir {
            format!("{}/", e.symlink_target.as_deref().unwrap_or(""))
        } else {
            e.symlink_target.clone().unwrap_or_default()
        };
        format!(
            "<a class=\"symlink\" href=\"{}\">{}<span class=\"symlink-symbol\"></span><a class=\"{}\">{}</a></a>",
            html_escape(&href),
            html_escape(&format!("{}{}", e.name, if e.is_dir { "/" } else { "" })),
            inner_cls,
            html_escape(&inner)
        )
    } else {
        name_link
    };
    let size_l = sort_link_for("size", &ctx.active_sort, ctx.active_order);
    let date_l = sort_link_for("date", &ctx.active_sort, ctx.active_order);
    let mobile_size = if c.size_display == SizeDisplay::Human {
        format!(
            "{sp}<span class=\"chevron\">{ch}</span><a href=\"?sort=size&amp;order={o}\" title=\"Sort by size in {d} order\">{s}</a></span>",
            sp = size_l.span_open(), ch = size_l.chevron, o = size_l.order, d = size_l.title_dir, s = html_escape(&size_str)
        )
    } else {
        html_escape(&size_str)
    };
    let mobile_date = format!(
        "{sp}<span class=\"chevron\">{ch}</span><a href=\"?sort=date&amp;order={o}\" title=\"Sort by date in {d} order\">{s}</a></span>",
        sp = date_l.span_open(), ch = date_l.chevron, o = date_l.order, d = date_l.title_dir, s = html_escape(&hist)
    );
    let dir_suffix = if e.is_dir { "/" } else { "" };
    let _ = dir_suffix;
    let rm_cell = if c.rm_files.is_some() {
        format!(
            "<td class=\"actions-cell\"><form class=\"rm_form\" action=\"{}{}?path={}\" method=\"POST\"><button type=\"submit\" title=\"Delete\">✗</button></form></td>",
            if ctx.state.route_prefix.is_empty() { "" } else { "/" },
            "rm",
            crate::util::percent_encode_path(&format!("{}{}", ctx.rel_path, e.name))
        )
    } else {
        String::new()
    };
    out.push_str(&format!(
        "<tr class=\"entry-type-{}\"><td><p>{}<span class=\"mobile-info size\">{}</span><span class=\"mobile-info history\">{}</span></p></td><td class=\"size-cell\">{}</td><td class=\"date-cell\"><span>{} </span><span class=\"history\">{}</span></td>{}</tr>",
        if e.is_dir { "directory" } else { "file" },
        name_cell,
        mobile_size,
        mobile_date,
        if e.is_dir { "" } else { &size_str },
        html_escape(&date_str),
        html_escape(&hist),
        rm_cell
    ));
}

pub fn render_error(state: &ServeState, status: u16, msg: &str, back: bool, back_href: &str) -> String {
    let base = format!("/{}", state.route_prefix);
    let favicon = format!("{}__miniserve_internal/favicon.svg", base);
    let style = format!("{}__miniserve_internal/style.css", base);
    let mut out = String::with_capacity(4096);
    out.push_str(include_str!("../assets/tpl/head_prefix.part"));
    out.push_str(&format!("{} {}", status, crate::http::Response::status_text(status)));
    out.push_str("</title>");
    out.push_str(include_str!("../assets/tpl/scheme.part"));
    out.push_str(include_str!("../assets/tpl/api.part"));
    out.push_str("</head><body><div class=\"error\">");
    out.push_str(&format!(
        "<p>{} {}</p><p>{}</p>",
        status,
        crate::http::Response::status_text(status),
        html_escape(msg)
    ));
    if back {
        out.push_str(&format!(
            "<div class=\"error-nav\"><a class=\"error-back\" href=\"{}\">Go back to file listing</a></div>",
            back_href
        ));
    }
    out.push_str(&format!("<p class=\"footer\"><div class=\"version\">{}</div></p>", VERSION_LINK));
    out.push_str("</div></body></html>");
    let _ = favicon;
    let _ = style;
    out
}
RUSTEOF
echo ok"}

