        Some(SortMethod::Date) => col == "date",
        None => false,
    };
    if is_active {
        match active_order {
            SortOrder::Asc => SortLink {
                active: true,
                chevron: "\u{25B4}",
                order: "desc",
                title_dir: "descending",
            },
            SortOrder::Desc => SortLink {
                active: true,
                chevron: "\u{25BE}",
                order: "asc",
                title_dir: "ascending",
            },
        }
    } else {
        SortLink {
            active: false,
            chevron: "\u{25BE}",
            order: "asc",
            title_dir: "ascending",
        }
    }
}

