        out.push_str(&format!("<div id=\"readme\"><h3 id=\"readme-filename\">{}</h3><div id=\"readme-contents\">{}</div></div>", html_escape(n), r));
    }
    out.push_str("<a class=\"back\" href=\"#top\">⇪</a><div class=\"footer\">");
    if c.show_wget_footer {
        out.push_str(&wget_footer(ctx));
    }
    if !c.hide_version_footer {
        out.push_str(&format!("<div class=\"version\">{}</div>", VERSION_LINK));
    }
    out.push_str("</div></div>");
    out.push_str(include_str!("../assets/tpl/upload_area.part"));
    out.push_str("</body></html>");
