use crate::config::{Config, SortMethod, SortOrder};
use std::path::{Path, PathBuf};

pub struct Entry {
    pub name: String,
    pub size: u64,
    pub mtime: i64,
    pub is_dir: bool,
    pub is_symlink: bool,
    pub symlink_target: Option<String>,
    pub path: PathBuf,
    pub dir_size: u64,
}

/// Read the entries of a directory, applying the filtering rules.
pub fn read_entries(c: &Config, dir: &Path) -> Vec<Entry> {
    let mut entries: Vec<Entry> = Vec::new();
    let rd = match std::fs::read_dir(dir) {
        Ok(r) => r,
        Err(_) => return entries,
    };
    for item in rd.flatten() {
        let name = item.file_name().to_string_lossy().to_string();
        let full = item.path();
        // metadata follows symlinks; entries that cannot be resolved are skipped
        let md = match std::fs::metadata(&full) {
            Ok(m) => m,
            Err(_) => continue,
        };
        let sl = std::fs::symlink_metadata(&full).ok().map(|m| m.file_type().is_symlink()).unwrap_or(false);
        if sl && c.no_symlinks {
            continue;
        }
        if !c.hidden && name.starts_with('.') {
            continue;
        }
        let mtime = md
            .modified()
            .ok()
            .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
            .map(|d| d.as_secs() as i64)
            .unwrap_or(0);
        let is_dir = md.is_dir();
        let target = if sl {
            std::fs::read_link(&full)
                .ok()
                .map(|p| p.to_string_lossy().to_string())
        } else {
            None
        };
        let dir_size = if c.directory_size && is_dir {
            crate::handler::dir_size(&full)
        } else {
            0
        };
        entries.push(Entry {
            name,
            size: md.len(),
            mtime,
            is_dir,
            is_symlink: sl,
            symlink_target: target,
            path: full,
            dir_size,
        });
    }
    entries
}

/// Sort the entries like miniserve does: for the "ascending" order the collection is
/// reversed before a stable ascending sort is applied.
pub fn sort_entries(c: &Config, entries: &mut Vec<Entry>, sort: SortMethod, order: SortOrder) {
    match sort {
        SortMethod::Name => match order {
            // name sorting is inverted relative to size/date
            SortOrder::Asc => entries.sort_by(|a, b| cmp_name(b, a)),
            SortOrder::Desc => entries.sort_by(|a, b| cmp_name(a, b)),
        },
        SortMethod::Size => match order {
            SortOrder::Asc => {
                entries.reverse();
                entries.sort_by(|a, b| key_size(a, c).cmp(&key_size(b, c)));
            }
            SortOrder::Desc => entries.sort_by(|a, b| key_size(b, c).cmp(&key_size(a, c))),
        },
        SortMethod::Date => match order {
            SortOrder::Asc => {
                entries.reverse();
                entries.sort_by(|a, b| a.mtime.cmp(&b.mtime));
            }
            SortOrder::Desc => entries.sort_by(|a, b| b.mtime.cmp(&a.mtime)),
        },
    }
}

fn cmp_name(a: &Entry, b: &Entry) -> std::cmp::Ordering {
    a.name.to_lowercase().cmp(&b.name.to_lowercase())
}

fn key_size(e: &Entry, c: &Config) -> u64 {
    if e.is_dir {
        if c.directory_size {
            e.dir_size
        } else {
            0
        }
    } else {
        e.size
    }
}

/// Parse the sort parameters of a request.
pub fn parse_sort(c: &Config, query: &str) -> (Option<SortMethod>, Option<SortOrder>, Option<SortMethod>, SortOrder) {
    let mut sort: Option<String> = None;
    let mut order: Option<String> = None;
    for pair in query.split('&') {
        if let Some(idx) = pair.find('=') {
            let k = &pair[..idx];
            let v = &pair[idx + 1..];
            if k == "sort" {
                sort = Some(v.to_string());
            } else if k == "order" {
                order = Some(v.to_string());
            }
        }
    }
    let s = sort.as_deref().and_then(|s| match s {
        "name" => Some(SortMethod::Name),
        "size" => Some(SortMethod::Size),
        "date" => Some(SortMethod::Date),
        _ => None,
    });
    let o = order.as_deref().and_then(|s| match s {
        "asc" => Some(SortOrder::Asc),
        "desc" => Some(SortOrder::Desc),
        _ => None,
    });
    match (s, o) {
        (Some(s), Some(o)) => (Some(s), Some(o), Some(s), o),
        _ => {
            let def = c.default_sorting_method;
            let defo = c.default_sorting_order;
            (None, None, Some(def), defo)
        }
    }
}

pub type SortKey = (Option<SortMethod>, SortOrder);
