use crate::config::{Config, SortMethod, SortOrder};
use crate::http::{Body, Request, Response};
use crate::server::ServeState;
use std::path::{Path, PathBuf};

pub fn dir_size(p: &Path) -> u64 {
    let mut total = 0u64;
    if let Ok(rd) = std::fs::read_dir(p) {
        for item in rd.flatten() {
            let path = item.path();
            if let Ok(md) = std::fs::symlink_metadata(&path) {
                if md.is_dir() {
                    total += dir_size(&path);
                } else {
                    total += md.len();
                }
            }
        }
    }
    total
}

/// Handle one request and produce a response.
pub fn handle(req: Request, state: &Arc<ServeState>) -> Response {
    let c = &state.cfg;

    // authentication
    if !c.auth.is_empty() {
        let ok = match req.header("authorization") {
            Some(v) => {
                let mut it = v.splitn(2, ' ');
                let scheme = it.next().unwrap_or("");
                let cred = it.next().unwrap_or("");
                if scheme.eq_ignore_ascii_case("basic") {
                    match base64_decode(cred) {
                        Some(decoded) => {
                            let s = String::from_utf_lossy(&decoded).to_string();
                            let mut it = s.splitn(2, ':');
                            let user = it.next().unwrap_or("");
                            let pass = it.next().unwrap_or("");
                            c.auth.iter().any(|a| a.verify(user, pass))
                        }
                        None => false,
                    }
                } else {
                    false
                }
            }
            None => false,
        };
        if !ok {
            if req.header("authorization").is_none() {
                return Response {
                    status: 401,
                    headers: vec![("www-authenticate".into(), "Basic".into())],
                    body: Body::Full(Vec::new()),
                    no_length: false,
                };
            }
            crate::log_error("Invalid credentials for HTTP authentication");
            let body = crate::render::render_error(state, 401, "", false, "/");
            return Response::text(401, "text/html", body);
        }
    }

    // strip the route prefix
    let prefix = &state.route_prefix;
    let target = if prefix.is_empty() {
        req.path.clone()
    } else {
        let p = &req.path;
        if p == format!("/{}", prefix) {
            "/".to_string()
        } else if let Some(rest) = p.strip_prefix(&format!("/{}/", prefix)) {
            format!("/{}", rest)
        } else {
            crate::log_error(&format!("Route {} could not be found", req.path));
            let body = crate::render::render_error(state, 404, &format!("Route {} could not be found", req.path), false, "/");
            return Response::text(404, "text/html", body);
        }
    };

    // internal routes
    let internal = "__miniserve_internal";
    if target == format!("/{}/style.css", internal) {
        return Response {
            status: 200,
            headers: vec![("content-type".into(), "text/css".into())],
            body: Body::Full(include_bytes!("../assets/tpl/style.css").to_vec()),
            no_length: false,
        };
    }
    if target == format!("/{}/favicon.svg", internal) {
        return Response {
            status: 200,
            headers: vec![("content-type".into(), "image/svg+xml".into())],
            body: Body::Full(include_bytes!("../data/logo.svg").to_vec()),
            no_length: false,
        };
    }
    if target == format!("/{}/api", internal) && c.directory_size {
        return api_handler(&req, state);
    }
    if target == format!("/{}/api", internal) {
        return error_response(state, 404, &format!("Route {} could not be found", req.path), true);
    }
    if target.starts_with(&format!("/{}/", internal)) {
        crate::log_error(&format!("Route {} could not be found", req.path));
        return error_response(state, 404, &format!("Route {} could not be found", req.path), true);
    }

    // upload / mkdir / rm endpoints
    if target == "/upload" {
        return crate::upload::handle_upload(&req, state);
    }
    if target == "/rm" {
        return crate::upload::handle_rm(&req, state);
    }

    // resolve the path inside the serve dir
    let rel = crate::util::percent_encode_path(&target);
    let full = resolve_path(state, &target);
    match full {
        Err(e) => {
            crate::log_error(&e.1);
            return e.0;
        }
        Ok((path, symlinked)) => {
            if req.method == "PROPFIND" && c.enable_webdav {
                return crate::webdav::handle_propfind(&req, state, &path, &target);
            }
            let md = match std::fs::metadata(&path) {
                Ok(m) => m,
                Err(e) => {
                    crate::log_error(&format!("Route {} could not be found", req.path));
                    return error_response(state, 404, &format!("Route {} could not be found", req.path), true);
                }
            };
            if md.is_dir() {
                // archive download?
                if let Some(kind) = query_param(&req.query, "download") {
                    return crate::archive::handle_download(&req, state, &path, &target, &kind);
                }
                if req.method == "POST" {
                    return error_response(state, 404, &format!("Route {} could not be found", req.path), true);
                }
                return listing_response(&req, state, &path, &target, symlinked);
            } else {
                if req.method != "GET" && req.method != "HEAD" {
                    crate::log_error(&format!("Route {} could not be found", req.path));
                    return error_response(state, 404, &format!("Route {} could not be found", req.path), true);
                }
                return serve_file(&req, state, &path);
            }
        }
    }
}

type Arc<T> = std::sync::Arc<T>;

pub fn error_response(state: &Arc<ServeState>, status: u16, msg: &str, back: bool) -> Response {
    let body = crate::render::render_error(state, status, msg, back, "/");
    Response::text(status, "text/html", body)
}

/// Resolve a URL path to a filesystem path inside the serve dir.
fn resolve_path(
    state: &Arc<ServeState>,
    target: &str,
) -> Result<(PathBuf, bool), (Response, String)> {
    let c = &state.cfg;
    let rel = target.trim_start_matches('/');
    let mut path = c.path.clone();
    let mut symlinked = false;
    if !rel.is_empty() {
        for part in rel.split('/') {
            if part.is_empty() || part == "." {
                continue;
            }
            if part == ".." {
                crate::log_error("Failed to resolve path to be served");
                return Err((error_response(state, 404, &format!("Route {} could not be found", crate::last_route()), true), String::new()));
            }
            path.push(part);
            if c.no_symlinks {
                if let Ok(md) = std::fs::symlink_metadata(&path) {
                    if md.file_type().is_symlink() {
                        symlinked = true;
                    }
                }
            }
        }
    }
    Ok((path, symlinked))
}

pub fn query_param(query: &str, key: &str) -> Option<String> {
    for pair in query.split('&') {
        if let Some(idx) = pair.find('=') {
            if &pair[..idx] == key {
                return Some(crate::http::url_decode(&pair[idx + 1..]));
            }
        } else if pair == key {
            return Some(String::new());
        }
    }
    None
}

pub fn has_query_key(query: &str, key: &str) -> bool {
    for pair in query.split('&') {
        if pair.split('=').next() == Some(key) {
            return true;
        }
    }
    false
}

/// Serve a directory listing (or the index file / SPA fallback).
fn listing_response(
    req: &Request,
    state: &Arc<ServeState>,
    path: &Path,
    target: &str,
    symlinked: bool,
) -> Response {
    let c = &state.cfg;
    if c.no_symlinks && symlinked {
        crate::log_error(&format!("Route {} could not be found", req.path));
        return error_response(state, 404, &format!("Route {} could not be found", req.path), true);
    }
    // index file
    if let Some(index) = &c.index_file {
        let ip = path.join(index);
        if std::fs::metadata(&ip).map(|m| m.is_file()).unwrap_or(false) {
            return serve_file(req, state, &ip);
        }
    }
    if c.disable_indexing {
        let msg = "Indexing is disabled".to_string();
        crate::log_error(&format!("Route {} could not be found", req.path));
        return error_response(state, 404, &format!("Route {} could not be found", req.path), true);
    }
    let (sort, order, active_sort, active_order) = crate::listing::parse_sort(c, &req.query);
    let mut entries = crate::listing::read_entries(c, path);
    crate::listing::sort_entries(c, &mut entries, active_sort, active_order);
    let depth = target.split('/').filter(|s| !s.is_empty()).count();
    let readme = if c.readme {
        let rp = path.join("README.md");
        match std::fs::read_to_string(&rp) {
            Ok(txt) => Some(crate::md::render(&txt)),
            Err(_) => None,
        }
    } else {
        None
    };
    let ctx = crate::render::ListingContext {
        state,
        req,
        rel_path: target,
        sort,
        order,
        active_sort,
        active_order,
        url_prefix: crate::util::percent_encode_path(target),
        page_title: crate::render::page_title(c, req),
        entries,
        readme,
        readme_name: if c.readme { Some("README.md".to_string()) } else { None },
        depth,
    };
    let body = crate::render::render_listing(&ctx);
    Response::text(200, "text/html; charset=utf-8", body)
}

/// Serve a single file with etag / last-modified / range support.
fn serve_file(req: &Request, state: &Arc<ServeState>, path: &Path) -> Response {
    let c = &state.cfg;
    let md = match std::fs::metadata(path) {
        Ok(m) => m,
        Err(_) => {
            crate::log_error(&format!("Route {} could not be found", req.path));
            return error_response(state, 404, &format!("Route {} could not be found", req.path), true);
        }
    };
    let mime = crate::mime::mime_type(path);
    let mut content_type = mime.0.to_string();
    if mime.1 {
        content_type.push_str("; charset=utf-8");
    }
    let disp = crate::mime::disposition(mime.0);
    let filename = path
        .file_name()
        .map(|n| n.to_string_lossy().to_string())
        .unwrap_or_default();
    let ino = crate::util::inode(path).unwrap_or(0);
    let mtime = md
        .modified()
        .ok()
        .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    let nanos = md
        .modified()
        .ok()
        .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
        .map(|d| d.subsec_nanos())
        .unwrap_or(0);
    let etag = format!(
        "\"{:x}:{:x}:{:x}:{:x}\"",
        ino,
        md.len(),
        mtime,
        nanos
    );
    let mut headers: Vec<(String, String)> = Vec::new();
    headers.push(("content-type".into(), content_type));
    headers.push((
        "content-disposition".into(),
        format!("{}; filename=\"{}\"", disp, crate::render::quote_filename(&filename)),
    ));
    headers.push(("last-modified".into(), crate::util::http_date(mtime)));
    headers.push(("etag".into(), etag.clone()));
    headers.push(("accept-ranges".into(), "bytes".into()));

    if req.method == "HEAD" {
        return Response {
            status: 200,
            headers,
            body: Body::Full(Vec::new()),
            no_length: false,
        };
    }

    if let Some(inm) = req.header("if-none-match") {
        if inm == etag {
            return Response {
                status: 304,
                headers,
                body: Body::Full(Vec::new()),
                no_length: true,
            };
        }
    }

    let data = match std::fs::read(path) {
        Ok(d) => d,
        Err(e) => {
            return error_response(state, 404, &format!("Route {} could not be found", req.path), true)
        }
    };

    if let Some(range) = req.header("range") {
        if let Some((start, end)) = parse_range(&range, data.len()) {
            let slice = data[start..=end].to_vec();
            headers.push((
                "content-range".into(),
                format!("bytes {}-{}/{}", start, end, data.len()),
            ));
            return Response {
                status: 200,
                headers,
                body: Body::Full(slice),
                no_length: false,
            };
        }
    }

    Response {
        status: 200,
        headers,
        body: Body::Full(data),
        no_length: false,
    }
}

fn parse_range(spec: &str, len: usize) -> Option<(usize, usize)> {
    let spec = spec.strip_prefix("bytes=")?;
    let mut it = spec.split('-');
    let a = it.next()?.trim();
    let b = it.next()?.trim();
    if a.is_empty() {
        let n: usize = b.parse().ok()?;
        if n == 0 || len == 0 {
            return None;
        }
        let start = len.saturating_sub(n);
        return Some((start, len - 1));
    }
    let start: usize = a.parse().ok()?;
    let end = if b.is_empty() { len - 1 } else { b.parse().ok()? };
    if start > end || end >= len {
        return None;
    }
    Some((start, end))
}

fn api_handler(req: &Request, state: &Arc<ServeState>) -> Response {
    // respond to the directory size API
    let body = String::from_utf_lossy(&req.body).to_string();
    let dir = extract_json_string(&body, "DirSize").unwrap_or_default();
    let rel = crate::http::url_decode(&dir);
    let full = state.cfg.path.join(rel.trim_start_matches('/'));
    let size = if full.is_dir() {
        crate::util::human_size(dir_size(&full))
    } else {
        "~".to_string()
    };
    Response::text(200, "text/plain", size)
}

fn extract_json_string(body: &str, key: &str) -> Option<String> {
    let pat = format!("\"{}\"", key);
    let idx = body.find(&pat)?;
    let rest = &body[idx + pat.len()..];
    let colon = rest.find(':')?;
    let rest = &rest[colon + 1..];
    let start = rest.find('"')?;
    let rest = &rest[start + 1..];
    let mut out = String::new();
    let mut it = rest.chars();
    while let Some(ch) = it.next() {
        match ch {
            '"' => break,
            '\\' => {
                if let Some(n) = it.next() {
                    out.push(n);
                }
            }
            _ => out.push(ch),
        }
    }
    Some(out)
}

pub fn base64_decode(s: &str) -> Option<Vec<u8>> {
    const T: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = Vec::new();
    let mut acc: u32 = 0;
    let mut bits = 0u32;
    for ch in s.bytes() {
        if ch == b'=' {
            break;
        }
        let v = T.iter().position(|&c| c == ch)? as u32;
        acc = (acc << 6) | v;
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            out.push(((acc >> bits) & 0xff) as u8);
        }
    }
    Some(out)
}
