/// Serve a single file with etag / last-modified / range support.
fn serve_file(req: &Request, state: &Arc<ServeState>, path: &Path) -> Response {
    let c = &state.cfg;
    let md = match std::fs::metadata(path) {
        Ok(m) => m,
        Err(_) => {
            crate::log_error(&format!("Route {} could not be found", req.path));
            return error_response(state, 404, &format!("Route {} could not be found", req.path), true);
        }
    };
    let mime = crate::mime::mime_type(path);
    let mut content_type = mime.0.to_string();
    if mime.1 {
        content_type.push_str("; charset=utf-8");
    }
    let disp = crate::mime::disposition(mime.0);
    let filename = path
        .file_name()
        .map(|n| n.to_string_lossy().to_string())
        .unwrap_or_default();
    let ino = crate::util::inode(path).unwrap_or(0);
    let mtime = md
        .modified()
        .ok()
        .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    let nanos = md
        .modified()
        .ok()
        .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
        .map(|d| d.subsec_nanos())
        .unwrap_or(0);
    let etag = format!(
        "\"{:x}:{:x}:{:x}:{:x}\"",
        ino,
        md.len(),
        mtime,
        nanos
    );
    let mut headers: Vec<(String, String)> = Vec::new();
    headers.push(("content-type".into(), content_type));
    headers.push((
        "content-disposition".into(),
        format!("{}; filename=\"{}\"", disp, crate::render::quote_filename(&filename)),
    ));
    headers.push(("last-modified".into(), crate::util::http_date(mtime)));
    headers.push(("etag".into(), etag.clone()));
    headers.push(("accept-ranges".into(), "bytes".into()));

    if req.method == "HEAD" {
        return Response {
            status: 200,
            headers,
            body: Body::Full(Vec::new()),
            no_length: false,
        };
    }

    if let Some(inm) = req.header("if-none-match") {
        if inm == etag {
            return Response {
                status: 304,
                headers,
                body: Body::Full(Vec::new()),
                no_length: true,
            };
        }
    }

    let data = match std::fs::read(path) {
        Ok(d) => d,
        Err(e) => {
            return error_response(state, 404, &format!("Route {} could not be found", req.path), true)
        }
    };

    if let Some(range) = req.header("range") {
        if let Some((start, end)) = parse_range(&range, data.len()) {
            let slice = data[start..=end].to_vec();
            headers.push((
                "content-range".into(),
                format!("bytes {}-{}/{}", start, end, data.len()),
            ));
            return Response {
                status: 200,
                headers,
                body: Body::Full(slice),
                no_length: false,
            };
        }
    }

    Response {
        status: 200,
        headers,
        body: Body::Full(data),
        no_length: false,
    }
}

fn parse_range(spec: &str, len: usize) -> Option<(usize, usize)> {
    let spec = spec.strip_prefix("bytes=")?;
    let mut it = spec.split('-');
    let a = it.next()?.trim();
    let b = it.next()?.trim();
    if a.is_empty() {
        let n: usize = b.parse().ok()?;
        if n == 0 || len == 0 {
            return None;
        }
        let start = len.saturating_sub(n);
        return Some((start, len - 1));
    }
    let start: usize = a.parse().ok()?;
    let end = if b.is_empty() { len - 1 } else { b.parse().ok()? };
    if start > end || end >= len {
        return None;
    }
    Some((start, end))
}

fn api_handler(req: &Request, state: &Arc<ServeState>) -> Response {
    // respond to the directory size API
    let body = String::from_utf_lossy(&req.body).to_string();
    let dir = extract_json_string(&body, "DirSize").unwrap_or_default();
    let rel = crate::http::url_decode(&dir);
    let full = state.cfg.path.join(rel.trim_start_matches('/'));
    let size = if full.is_dir() {
        crate::util::human_size(dir_size(&full))
    } else {
        "~".to_string()
    };
    Response::text(200, "text/plain", size)
}

fn extract_json_string(body: &str, key: &str) -> Option<String> {
    let pat = format!("\"{}\"", key);
    let idx = body.find(&pat)?;
    let rest = &body[idx + pat.len()..];
    let colon = rest.find(':')?;
    let rest = &rest[colon + 1..];
    let start = rest.find('"')?;
    let rest = &rest[start + 1..];
    let mut out = String::new();
    let mut it = rest.chars();
    while let Some(ch) = it.next() {
        match ch {
            '"' => break,
            '\\' => {
                if let Some(n) = it.next() {
                    out.push(n);
                }
            }
            _ => out.push(ch),
        }
    }
    Some(out)
}

pub fn base64_decode(s: &str) -> Option<Vec<u8>> {
    const T: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = Vec::new();
    let mut acc: u32 = 0;
    let mut bits = 0u32;
    for ch in s.bytes() {
        if ch == b'=' {
            break;
        }
        let v = T.iter().position(|&c| c == ch)? as u32;
        acc = (acc << 6) | v;
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            out.push(((acc >> bits) & 0xff) as u8);
        }
    }
    Some(out)
}
