                    ok2 = false;
                    break;
                }
                let v = m.get(x + k, y);
                if v != pat1[k] {
                    ok1 = false;
                }
                if v != pat2[k] {
                    ok2 = false;
                }
            }
            if ok1 || ok2 {
                score += 40;
            }
        }
    }
    for x in 0..size {
        for y in 0..size {
            let mut ok1 = true;
            let mut ok2 = true;
            for k in 0..11 {
                if y + k >= size {
                    ok1 = false;
                    ok2 = false;
                    break;
                }
                let v = m.get(x, y + k);
                if v != pat1[k] {
                    ok1 = false;
                }
                if v != pat2[k] {
                    ok2 = false;
                }
            }
            if ok1 || ok2 {
                score += 40;
            }
        }
    }
    // Rule 4: dark module proportion
    let dark: usize = m.modules.iter().filter(|&&d| d).count();
    let total = size * size;
    let ratio = dark * 100 / total;
    let mut prev = 10;
    let mut k = 5;
    while ratio < k {
        prev -= 2;
        k -= 5;
    }
    k = 5;
    let mut next = 0;
    while ratio > k {
        next += 2;
        k += 5;
    }
    let dev = prev.min(next);
    score += dev as i32 * 10;
    score
}

/// Build the QR matrix for the given text.
pub fn encode(text: &str) -> (usize, Vec<bool>) {
    let data = text.as_bytes();
    // choose the smallest version that fits with EC level L
    let mut version = 1;
    loop {
        let t = EC_L_TABLE[version - 1];
        let total_bits = t.1 * 8;
        let capacity_bits = version_size(version) * version_size(version) / 8 * 8;
        let header_bits = 4 + if version < 10 { 8 } else { 16 };
        let data_bits = data.len() * 8;
        if header_bits + data_bits <= total_bits {
            break;
        }
        version += 1;
        if version > 40 {
            break;
        }
    }
    let t = EC_L_TABLE[version - 1];
    let total_data = t.1;
    let mut bits: Vec<bool> = Vec::new();
    bit_buffer_push(&mut bits, 4, 4); // byte mode
    if version < 10 {
        bit_buffer_push(&mut bits, data.len() as u32, 8);
    } else {
        bit_buffer_push(&mut bits, data.len() as u32, 16);
    }
    for &b in data {
        bit_buffer_push(&mut bits, b as u32, 8);
    }
    // terminator
    let capacity_bits = total_data * 8;
    let term = std::cmp::min(4, capacity_bits - bits.len());
    bit_buffer_push(&mut bits, 0, term);
    // pad to byte
    while bits.len() % 8 != 0 {
        bits.push(false);
    }
    let mut codewords: Vec<u8> = Vec::new();
    for chunk in bits.chunks(8) {
        let mut v = 0u8;
        for (i, &b) in chunk.iter().enumerate() {
            if b {
                v |= 1 << (7 - i);
            }
        }
        codewords.push(v);
    }
    let pad = [0xecu8, 0x11u8];
    let mut i = 0;
    while codewords.len() < total_data {
        codewords.push(pad[i % 2]);
        i += 1;
    }
    // error correction
    let (_log, _exp) = gf_tables();
    let (log, exp) = gf_tables();
    let gen = rs_generator(t.2, &log, &exp);
    let ecc = rs_encode(&codewords, &gen, &log, &exp);

    // interleave (single block case for low versions)
    let mut blocks: Vec<Vec<u8>> = Vec::new();
    let mut ec_blocks: Vec<Vec<u8>> = Vec::new();
    let mut idx = 0;
    let g1_count = t.3;
    let g1_len = t.4;
    let g2_count = t.5;
    let g2_len = t.6;
    for _ in 0..g1_count {
        blocks.push(codewords[idx..idx + g1_len].to_vec());
        ec_blocks.push(ecc[0..t.2].to_vec());
        idx += g1_len;
    }
    for _ in 0..g2_count {
        blocks.push(codewords[idx..idx + g2_len].to_vec());
        ec_blocks.push(ecc[0..t.2].to_vec());
        idx += g2_len;
    }
    let mut interleaved: Vec<u8> = Vec::new();
    let max_len = blocks.iter().map(|b| b.len()).max().unwrap_or(0);
    for i in 0..max_len {
        for b in &blocks {
            if i < b.len() {
                interleaved.push(b[i]);
            }
        }
    }
    for i in 0..t.2 {
        for b in &ec_blocks {
            if i < b.len() {
                interleaved.push(b[i]);
            }
        }
    }

    // choose the best mask
    let size = version_size(version);
    let mut best: Option<(i32, usize, Matrix)> = None;
    for mask in 0..8 {
        let mut m = Matrix::new(size);
        draw_function_patterns(&mut m, version);
        place_data(&mut m, &interleaved);
        draw_format(&mut m, mask, EC_L);
        draw_version(&mut m, version);
        apply_mask(&mut m, mask);
        let p = penalty(&m);
        if best.is_none() || p < best.as_ref().unwrap().0 {
            best = Some((p, mask, m));
        }
    }
    let (_, _mask, m) = best.unwrap();
    (size, m.modules)
}

fn draw_function_patterns(m: &mut Matrix, version: usize) {
    let size = m.size as isize;
    draw_finder(m, 3, 3);
    draw_finder(m, size - 4, 3);
    draw_finder(m, 3, size - 4);
    // separators are drawn as part of the finder pattern
    // timing patterns
    for i in 8..size - 8 {
        let dark = i % 2 == 0;
        m.set_function(i, 6, dark);
        m.set_function(6, i, dark);
    }
    // alignment patterns
    let pos = alignment_positions(version);
    for &py in &pos {
        for &px in &pos {
            if (px == 6 && py == 6) || (px == 6 && py == size - 7) || (px == size - 7 && py == 6) {
                continue;
            }
            draw_alignment(m, px as isize, py as isize);
        }
    }
    // format info placeholder
    for (x, y) in [
        (8, 0), (8, 1), (8, 2), (8, 3), (8, 4), (8, 5), (8, 7), (8, 8), (7, 8),
        (5, 8), (4, 8), (3, 8), (2, 8), (1, 8), (0, 8),
    ] {
        m.set_function(x, y, false);
    }
    let s = size;
    for (x, y) in [
        (s - 1, 8), (s - 2, 8), (s - 3, 8), (s - 4, 8), (s - 5, 8), (s - 6, 8),
        (s - 7, 8), (8, s - 8), (8, s - 7), (8, s - 6), (8, s - 5), (8, s - 4),
        (8, s - 3), (8, s - 2), (8, s - 1),
    ] {
        m.set_function(x, y, false);
    }
    // dark module
    m.set_function(8, size - 8, true);
}

fn place_data(m: &mut Matrix, data: &[u8]) {
    let size = m.size as isize;
    let mut bit_idx = 0usize;
    let total_bits = data.len() * 8;
    let mut i = 0isize;
    let mut right = true;
    while i >= 0 {
        let cols = if right { 2 } else { 2 };
        for dy in 0..size {
            let y = if (i as usize) % 2 == 0 {
                size - 1 - dy
            } else {
                dy
            };
            for dx in 0..cols {
                let x = i - dx;
                if x < 0 {
                    continue;
                }
                if m.function[y as usize * m.size + x as usize] {
                    continue;
                }
                let dark = if bit_idx < total_bits {
                    let byte = data[bit_idx / 8];
                    (byte >> (7 - (bit_idx % 8))) & 1 == 1
                } else {
                    false
                };
                m.modules[y as usize * m.size + x as usize] = dark;
                bit_idx += 1;
            }
        }
        right = !right;
        i -= 2;
    }
}

/// Produce the SVG path data for the QR code, plus the module size (including the quiet zone).
pub fn qr_svg(text: &str) -> (usize, String) {
    let (size, modules) = encode(text);
    let n = size + 2;
    let mut path = String::new();
    for y in 0..size {
        for x in 0..size {
            if modules[y * size + x] {
                path.push_str(&format!("M{},{}h1v1h-1", x + 1, y + 1));
            }
        }
    }
    (n, path)
}
