fn version_size(version: usize) -> usize {
    version * 4 + 17
}

// Galois field arithmetic over GF(256) with the QR primitive polynomial
fn gf_tables() -> ([u8; 256], [u8; 256]) {
    let mut log = [0u8; 256];
    let mut exp = [0u8; 512];
    let mut x: u16 = 1;
    for i in 0..255 {
        exp[i] = x as u8;
        log[x as usize] = i as u8;
        x <<= 1;
        if x & 0x100 != 0 {
            x ^= 0x11d;
        }
    }
    for i in 255..512 {
        exp[i] = exp[i - 255];
    }
    (log, exp)
}

fn rs_generator(degree: usize, log: &[u8; 256], exp: &[u8; 512]) -> Vec<u8> {
    let mut poly = vec![1u8];
    for i in 0..degree {
        let mut new = vec![0u8; poly.len() + 1];
        for (j, &p) in poly.iter().enumerate() {
            new[j] ^= p;
            let a = if p == 0 { 0 } else { log[p as usize] as usize };
            let m = exp[(a + i) % 255];
            new[j + 1] ^= m;
        }
        poly = new;
    }
    poly
}

fn rs_encode(data: &[u8], gen: &[u8], log: &[u8; 256], exp: &[u8; 512]) -> Vec<u8> {
    let degree = gen.len() - 1;
    let mut res = vec![0u8; degree];
    for &d in data {
        let factor = d ^ res[0];
        res.remove(0);
        res.push(0);
        if factor != 0 {
            let lf = log[factor as usize] as usize;
            for j in 0..degree {
                let g = gen[j + 1];
                if g != 0 {
                    res[j] ^= exp[(log[g as usize] as usize + lf) % 255];
                }
            }
        }
    }
    res
}

fn bit_buffer_push(bits: &mut Vec<bool>, value: u32, len: usize) {
    for i in (0..len).rev() {
        bits.push((value >> i) & 1 == 1);
    }
}

struct Matrix {
    size: usize,
    modules: Vec<bool>,
    function: Vec<bool>,
}

impl Matrix {
    fn new(size: usize) -> Matrix {
        Matrix {
            size,
            modules: vec![false; size * size],
            function: vec![false; size * size],
        }
    }
    fn set(&mut self, x: isize, y: isize, dark: bool) {
        if x < 0 || y < 0 || x as usize >= self.size || y as usize >= self.size {
            return;
        }
        self.modules[y as usize * self.size + x as usize] = dark;
        self.function[y as usize * self.size + x as usize] = true;
    }
    fn get(&self, x: usize, y: usize) -> bool {
        self.modules[y * self.size + x]
    }
    fn set_function(&mut self, x: isize, y: isize, dark: bool) {
        self.set(x, y, dark);
    }
}

fn draw_finder(m: &mut Matrix, x: isize, y: isize) {
    for dy in -4..=4 {
        for dx in -4..=4 {
            let dist = dx.abs().max(dy.abs());
            let dark = dist != 2 && dist != 4;
            m.set_function(x + dx, y + dy, dark);
        }
    }
}

fn draw_alignment(m: &mut Matrix, x: isize, y: isize) {
    for dy in -2..=2 {
        for dx in -2..=2 {
            let dist = dx.abs().max(dy.abs());
            let dark = dist != 1;
            m.set_function(x + dx, y + dy, dark);
        }
    }
}

fn alignment_positions(version: usize) -> Vec<usize> {
    if version == 1 {
        return vec![];
    }
    let size = version_size(version);
    let num = version / 7 + 2;
    let step = if version == 32 {
        26
    } else {
        (version * 4 + num * 2 + 1) / (num * 2 - 2) * 2
    };
    let mut pos = Vec::new();
    let mut p = size - 7;
    pos.push(6);
    while p > step {
        pos.push(p);
        p -= step;
    }
    pos.push(6);
    pos
}

fn draw_format(m: &mut Matrix, mask: usize, ec_level: usize) {
    let data = format_bits(ec_level, mask);
    // first copy
    let coords: [(isize, isize); 15] = [
        (8, 0), (8, 1), (8, 2), (8, 3), (8, 4), (8, 5), (8, 7), (8, 8), (7, 8),
        (5, 8), (4, 8), (3, 8), (2, 8), (1, 8), (0, 8),
    ];
    for (i, &(x, y)) in coords.iter().enumerate() {
        m.set_function(x, y, (data >> (14 - i)) & 1 == 1);
