        (size - 7, 8), (8, size - 8), (8, size - 7), (8, size - 6), (8, size - 5),
        (8, size - 4), (8, size - 3), (8, size - 2), (8, size - 1),
    ];
    for (i, &(x, y)) in coords2.iter().enumerate() {
        m.set_function(x, y, (data >> i) & 1 == 1);
