/// Build the QR matrix for the given text.
pub fn encode(text: &str) -> (usize, Vec<bool>) {
    let data = text.as_bytes();
    // choose the smallest version that fits with EC level L
    let mut version = 1;
    loop {
        let t = EC_L_TABLE[version - 1];
        let total_bits = t.1 * 8;
        let capacity_bits = version_size(version) * version_size(version) / 8 * 8;
        let header_bits = 4 + if version < 10 { 8 } else { 16 };
        let data_bits = data.len() * 8;
        if header_bits + data_bits <= total_bits {
            break;
        }
        version += 1;
        if version > 40 {
            break;
        }
    }
    let t = EC_L_TABLE[version - 1];
    let total_data = t.1;
    let mut bits: Vec<bool> = Vec::new();
    bit_buffer_push(&mut bits, 4, 4); // byte mode
    if version < 10 {
        bit_buffer_push(&mut bits, data.len() as u32, 8);
    } else {
        bit_buffer_push(&mut bits, data.len() as u32, 16);
    }
    for &b in data {
        bit_buffer_push(&mut bits, b as u32, 8);
    }
    // terminator
    let capacity_bits = total_data * 8;
    let term = std::cmp::min(4, capacity_bits - bits.len());
    bit_buffer_push(&mut bits, 0, term);
    // pad to byte
    while bits.len() % 8 != 0 {
        bits.push(false);
    }
    let mut codewords: Vec<u8> = Vec::new();
    for chunk in bits.chunks(8) {
        let mut v = 0u8;
        for (i, &b) in chunk.iter().enumerate() {
            if b {
                v |= 1 << (7 - i);
            }
        }
        codewords.push(v);
    }
    let pad = [0xecu8, 0x11u8];
    let mut i = 0;
    while codewords.len() < total_data {
        codewords.push(pad[i % 2]);
        i += 1;
    }
    // error correction
    let (_log, _exp) = gf_tables();
    let (log, exp) = gf_tables();
    let gen = rs_generator(t.2, &log, &exp);
    let ecc = rs_encode(&codewords, &gen, &log, &exp);

    // interleave (single block case for low versions)
    let mut blocks: Vec<Vec<u8>> = Vec::new();
    let mut ec_blocks: Vec<Vec<u8>> = Vec::new();
    let mut idx = 0;
    let g1_count = t.3;
    let g1_len = t.4;
    let g2_count = t.5;
    let g2_len = t.6;
    for _ in 0..g1_count {
        blocks.push(codewords[idx..idx + g1_len].to_vec());
        ec_blocks.push(ecc[0..t.2].to_vec());
        idx += g1_len;
    }
    for _ in 0..g2_count {
        blocks.push(codewords[idx..idx + g2_len].to_vec());
        ec_blocks.push(ecc[0..t.2].to_vec());
        idx += g2_len;
    }
    let mut interleaved: Vec<u8> = Vec::new();
    let max_len = blocks.iter().map(|b| b.len()).max().unwrap_or(0);
    for i in 0..max_len {
        for b in &blocks {
            if i < b.len() {
                interleaved.push(b[i]);
            }
        }
    }
    for i in 0..t.2 {
        for b in &ec_blocks {
            if i < b.len() {
                interleaved.push(b[i]);
            }
        }
    }

    // choose the best mask
    let size = version_size(version);
    let mut best: Option<(i32, usize, Matrix)> = None;
    for mask in 0..8 {
        let mut m = Matrix::new(size);
        draw_function_patterns(&mut m, version);
        place_data(&mut m, &interleaved);
        draw_format(&mut m, mask, EC_L);
        draw_version(&mut m, version);
        apply_mask(&mut m, mask);
        let p = penalty(&m);
        if best.is_none() || p < best.as_ref().unwrap().0 {
            best = Some((p, mask, m));
        }
    }
    let (_, _mask, m) = best.unwrap();
    (size, m.modules)
}

fn draw_function_patterns(m: &mut Matrix, version: usize) {
    let size = m.size as isize;
    draw_finder(m, 3, 3);
    draw_finder(m, size - 4, 3);
    draw_finder(m, 3, size - 4);
    // separators are drawn as part of the finder pattern
    // timing patterns
    for i in 8..size - 8 {
        let dark = i % 2 == 0;
        m.set_function(i, 6, dark);
        m.set_function(6, i, dark);
    }
    // alignment patterns
    let pos = alignment_positions(version);
    for &py in &pos {
        for &px in &pos {
            if (px == 6 && py == 6) || (px == 6 && py == size - 7) || (px == size - 7 && py == 6) {
                continue;
            }
