use crate::http::{Body, Request, Response};
use crate::server::ServeState;
use std::sync::Arc;

pub fn handle_download(
    req: &Request,
    state: &Arc<ServeState>,
    path: &std::path::Path,
    target: &str,
    kind: &str,
) -> Response {
    let c = &state.cfg;
    match kind {
        "tar" if c.enable_tar => {
            let data = build_tar(path, target);
            let name = archive_name(target, "tar");
            Response {
                status: 200,
                headers: vec![
                    ("content-type".into(), "application/tar".into()),
                    ("content-transfer-encoding".into(), "binary".into()),
                    ("content-disposition".into(), format!("attachment; filename=\"{}\"", name)),
                ],
                body: Body::Stream(Box::new(move |w: &mut dyn std::io::Write| {
                    w.write_all(&data)
                })),
                no_length: false,
            }
        }
        "tar_gz" if c.enable_tar_gz => {
            let data = build_tar(path, target);
            let gz = crate::util::gzip(&data);
            let name = archive_name(target, "tar.gz");
            Response {
                status: 200,
                headers: vec![
                    ("content-type".into(), "application/x-tar+gzip".into()),
                    ("content-transfer-encoding".into(), "binary".into()),
                    ("content-disposition".into(), format!("attachment; filename=\"{}\"", name)),
                ],
                body: Body::Stream(Box::new(move |w: &mut dyn std::io::Write| {
                    w.write_all(&gz)
                })),
                no_length: false,
            }
        }
        "zip" if c.enable_zip => {
            let data = build_zip(path, target);
            let name = archive_name(target, "zip");
            Response {
                status: 200,
                headers: vec![
                    ("content-type".into(), "application/zip".into()),
                    ("content-transfer-encoding".into(), "binary".into()),
                    ("content-disposition".into(), format!("attachment; filename=\"{}\"", name)),
                ],
                body: Body::Stream(Box::new(move |w: &mut dyn std::io::Write| {
                    w.write_all(&data)
                })),
                no_length: false,
            }
        }
        _ => {
            let msg = "Archive creation is disabled.".to_string();
            crate::log_error(&msg);
            Response::text(403, "text/html", crate::render::render_error(state, 403, &msg, true, "/"))
        }
    }
}

fn archive_name(target: &str, ext: &str) -> String {
    let base = target.trim_matches('/');
    let base = if base.is_empty() { "" } else { base.rsplit('/').next().unwrap_or(base) };
    format!("{}.{}", base, ext)
}

/// Build an uncompressed tar archive of a directory.
pub fn build_tar(path: &std::path::Path, prefix: &str) -> Vec<u8> {
    let mut out: Vec<u8> = Vec::new();
    let base = prefix.trim_matches('/').to_string();
    add_dir_to_tar(path, &base, &mut out);
    // two 512-byte zero blocks as end of archive
    out.extend(std::iter::repeat(0u8).take(1024));
    out
}

fn add_dir_to_tar(path: &std::path::Path, prefix: &str, out: &mut Vec<u8>) {
    let mut entries: Vec<std::fs::DirEntry> = match std::fs::read_dir(path) {
        Ok(r) => r.flatten().collect(),
        Err(_) => return,
    };
    entries.sort_by(|a, b| a.file_name().cmp(&b.file_name()));
    if !prefix.is_empty() {
        let name = format!("{}/", prefix);
        let header = tar_header(&name, 0, 0o40755, 0, 5);
        out.extend_from_slice(&header);
    }
    for e in entries {
        let full = e.path();
        let name = if prefix.is_empty() {
            e.file_name().to_string_lossy().to_string()
        } else {
            format!("{}/{}", prefix, e.file_name().to_string_lossy())
        };
        let md = match std::fs::metadata(&full) {
            Ok(m) => m,
            Err(_) => continue,
        };
        if md.is_dir() {
            let dirname = format!("{}/", name);
            out.extend_from_slice(&tar_header(&dirname, 0, 0o40755, 0, 5));
            add_dir_to_tar(&full, &name, out);
        } else {
            let data = std::fs::read(&full).unwrap_or_default();
            out.extend_from_slice(&tar_header(&name, data.len(), 0o100644, mtime_of(&md), 0));
            out.extend_from_slice(&data);
            let pad = (512 - (data.len() % 512)) % 512;
            out.extend(std::iter::repeat(0u8).take(pad));
        }
    }
}

fn mtime_of(md: &std::fs::Metadata) -> u64 {
    md.modified()
        .ok()
        .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
        .map(|d| d.as_secs())
        .unwrap_or(0)
}

fn tar_header(name: &str, size: usize, mode: u32, mtime: u64, typ: u8) -> [u8; 512] {
    let mut h = [0u8; 512];
    let name_bytes = name.as_bytes();
    let n = name_bytes.len().min(100);
    h[..n].copy_from_slice(&name_bytes[..n]);
    write_octal(&mut h[100..108], (mode & 0o7777) as u64);
    write_octal(&mut h[108..116], 0);
    write_octal(&mut h[116..124], 0);
    write_octal(&mut h[124..136], size as u64);
    write_octal(&mut h[136..148], mtime);
    h[156] = b'0' + typ;
    h[257..262].copy_from_slice(b"ustar");
    h[263..265].copy_from_slice(b"00");
    let mut checksum: u64 = 0;
    for &b in h.iter() {
        checksum += b as u64;
    }
    write_octal(&mut h[148..156], checksum);
    h[155] = b' ';
    h
}

fn write_octal(buf: &mut [u8], mut val: u64) {
    let n = buf.len();
    let mut tmp = [0u8; 24];
    let mut i = 0;
    if val == 0 {
        tmp[0] = b'0';
        i = 1;
    }
    while val > 0 {
        tmp[i] = b'0' + (val % 8) as u8;
        val /= 8;
        i += 1;
    }
    let digits = i;
    for j in 0..(n - 1) {
        buf[j] = b'0';
    }
    let start = n - 1 - digits;
    for j in 0..digits {
        buf[start + j] = tmp[digits - 1 - j];
    }
    buf[n - 1] = b' ';
}

/// Build a zip archive of a directory (stored, no compression).
pub fn build_zip(path: &std::path::Path, prefix: &str) -> Vec<u8> {
    let mut out: Vec<u8> = Vec::new();
    let mut central: Vec<u8> = Vec::new();
    let mut count = 0u16;
    let base = prefix.trim_matches('/').to_string();
    zip_add_dir(path, &base, &mut out, &mut central, &mut count);
    let cd_offset = out.len() as u32;
    out.extend_from_slice(&central);
    let cd_size = central.len() as u32;
    // end of central directory
    let mut eocd = Vec::new();
    eocd.extend_from_slice(&[0x50, 0x4b, 0x05, 0x06]);
    eocd.extend_from_slice(&0u16.to_le_bytes());
    eocd.extend_from_slice(&0u16.to_le_bytes());
    eocd.extend_from_slice(&count.to_le_bytes());
    eocd.extend_from_slice(&count.to_le_bytes());
    eocd.extend_from_slice(&cd_size.to_le_bytes());
    eocd.extend_from_slice(&cd_offset.to_le_bytes());
    eocd.extend_from_slice(&0u16.to_le_bytes());
    out.extend_from_slice(&eocd);
    out
}

fn zip_add_dir(
    path: &std::path::Path,
    prefix: &str,
    out: &mut Vec<u8>,
    central: &mut Vec<u8>,
    count: &mut u16,
) {
    let mut entries: Vec<std::fs::DirEntry> = match std::fs::read_dir(path) {
        Ok(r) => r.flatten().collect(),
        Err(_) => return,
    };
    entries.sort_by(|a, b| a.file_name().cmp(&b.file_name()));
    for e in entries {
        let full = e.path();
        let name = if prefix.is_empty() {
            e.file_name().to_string_lossy().to_string()
        } else {
            format!("{}/{}", prefix, e.file_name().to_string_lossy())
        };
        let md = match std::fs::metadata(&full) {
            Ok(m) => m,
            Err(_) => continue,
        };
        if md.is_dir() {
            let dirname = format!("{}/", name);
            write_zip_entry(out, central, count, &dirname, &[], true, mtime_of(&md));
            zip_add_dir(&full, &name, out, central, count);
        } else {
            let data = std::fs::read(&full).unwrap_or_default();
            write_zip_entry(out, central, count, &name, &data, false, mtime_of(&md));
        }
    }
}

fn dos_time(secs: u64) -> (u16, u16) {
    let (y, mo, d, h, mi, s) = crate::util::civil_from_epoch(secs as i64);
    let year = (y as u32).max(1980) - 1980;
    let date = (year << 9) | ((mo as u32) << 5) | (d as u32);
    let time = ((h as u32) << 11) | ((mi as u32) << 5) | ((s as u32) / 2);
    (time as u16, date as u16)
}

fn write_zip_entry(
    out: &mut Vec<u8>,
    central: &mut Vec<u8>,
    count: &mut u16,
    name: &str,
    data: &[u8],
    is_dir: bool,
    mtime: u64,
) {
    let offset = out.len() as u32;
    let crc = crc32(data);
    let (time, date) = dos_time(mtime);
    let name_b = name.as_bytes();
    let method: u16 = if is_dir { 0 } else { 8 };
    let (stored, comp): (Vec<u8>, usize) = if is_dir {
        (Vec::new(), 0)
    } else {
        let mut e = crate::util::deflate_raw(data);
        (e.drain(..).collect(), data.len())
    };
    let _ = stored;
    let comp_data = if is_dir { Vec::new() } else { deflate_data(data) };
    let _ = comp;
    out.extend_from_slice(&[0x50, 0x4b, 0x03, 0x04]);
    out.extend_from_slice(&20u16.to_le_bytes());
    out.extend_from_slice(&0u16.to_le_bytes());
    out.extend_from_slice(&method.to_le_bytes());
    out.extend_from_slice(&time.to_le_bytes());
    out.extend_from_slice(&date.to_le_bytes());
    out.extend_from_slice(&crc.to_le_bytes());
    out.extend_from_slice(&(comp_data.len() as u32).to_le_bytes());
    out.extend_from_slice(&(data.len() as u32).to_le_bytes());
    out.extend_from_slice(&(name_b.len() as u16).to_le_bytes());
    out.extend_from_slice(&0u16.to_le_bytes());
    out.extend_from_slice(name_b);
    out.extend_from_slice(&comp_data);

    central.extend_from_slice(&[0x50, 0x4b, 0x01, 0x02]);
    central.extend_from_slice(&20u16.to_le_bytes());
    central.extend_from_slice(&20u16.to_le_bytes());
    central.extend_from_slice(&0u16.to_le_bytes());
    central.extend_from_slice(&method.to_le_bytes());
    central.extend_from_slice(&time.to_le_bytes());
    central.extend_from_slice(&date.to_le_bytes());
    central.extend_from_slice(&crc.to_le_bytes());
    central.extend_from_slice(&(comp_data.len() as u32).to_le_bytes());
    central.extend_from_slice(&(data.len() as u32).to_le_bytes());
    central.extend_from_slice(&(name_b.len() as u16).to_le_bytes());
    central.extend_from_slice(&0u16.to_le_bytes());
    central.extend_from_slice(&0u16.to_le_bytes());
    central.extend_from_slice(&0u16.to_le_bytes());
    central.extend_from_slice(&0u16.to_le_bytes());
    central.extend_from_slice(&(if is_dir { 0o40755u32 } else { 0o100644u32 } << 16).to_le_bytes());
    central.extend_from_slice(&offset.to_le_bytes());
    central.extend_from_slice(name_b);
    *count += 1;
}

fn deflate_data(data: &[u8]) -> Vec<u8> {
    crate::util::deflate_raw(data)
}

pub fn crc32(data: &[u8]) -> u32 {
    let mut h = crc32fast::Hasher::new();
    h.update(data);
    h.finalize()
}
RUSTEOF
echo ok"}

