use crate::config::OnDuplicate;
use crate::http::{Body, Request, Response};
use crate::server::ServeState;
use std::sync::Arc;

fn error(state: &Arc<ServeState>, status: u16, msg: &str) -> Response {
    crate::log_error(msg);
    Response::text(status, "text/html", crate::render::render_error(state, status, msg, true, "/"))
}

/// Handle POST requests to /upload (file uploads and directory creation).
pub fn handle_upload(req: &Request, state: &Arc<ServeState>) -> Response {
    let c = &state.cfg;
    if c.upload_files.is_none() {
        return error(state, 404, &format!("Route {} could not be found", req.path));
    }
    let target_dir = crate::handler::query_param(&req.query, "path").unwrap_or_else(|| "/".to_string());
    let decoded = crate::http::url_decode(&target_dir);
    // mkdir form?
    let ctype = req.header("content-type").unwrap_or("").to_string();
    if ctype.starts_with("application/x-www-form-urlencoded") {
        let body = String::from_utf_lossy(&req.body).to_string();
        if let Some(name) = form_param(&body, "mkdir") {
            return handle_mkdir(state, &decoded, &name);
        }
        return error(state, 400, "Missing directory name");
    }
    if !ctype.starts_with("multipart/form-data") {
        return error(state, 415, "Unsupported media type");
    }
    let boundary = match ctype.split(';').map(|s| s.trim()).find(|s| s.starts_with("boundary=")) {
        Some(b) => b[9..].trim_matches('"').to_string(),
        None => return error(state, 400, "Missing multipart boundary"),
    };
    let parts = split_multipart(&req.body, &boundary);
    let mut uploaded: Vec<String> = Vec::new();
    for part in parts {
        let (_, filename, data) = match part {
            Some(p) => p,
            None => continue,
        };
        let filename = match filename {
            Some(f) => f,
            None => continue,
        };
        if let Err(e) = write_uploaded_file(state, &decoded, &filename, data) {
            return error(state, 500, &e);
        }
        uploaded.push(filename);
    }
    Response {
        status: 200,
        headers: vec![("content-type".into(), "text/html; charset=utf-8".into())],
        body: Body::Full(Vec::new()),
        no_length: false,
    }
}

fn handle_mkdir(state: &Arc<ServeState>, dir: &str, name: &str) -> Response {
    let c = &state.cfg;
    if !c.mkdir_enabled {
        return error(state, 403, "Directory creation is disabled");
    }
    let base = c.path.join(dir.trim_start_matches('/'));
    let target = base.join(crate::http::url_decode(name));
    if let Err(e) = std::fs::create_dir(&target) {
        return error(state, 500, &format!("Failed to create directory: {}", e));
    }
    if let Some(mode) = c.chmod {
        use std::os::unix::fs::PermissionsExt;
        let _ = std::fs::set_permissions(&target, std::fs::Permissions::from_mode(mode));
    }
    Response::text(200, "text/html; charset=utf-8", String::new())
}

fn write_uploaded_file(
    state: &Arc<ServeState>,
    dir: &str,
    name: &str,
    data: &[u8],
) -> Result<(), String> {
    let c = &state.cfg;
    let base = c.path.join(dir.trim_start_matches('/'));
    let mut target = base.join(crate::http::url_decode(name));
    match c.on_duplicate_files {
        OnDuplicate::Error => {
            if target.exists() {
                return Err(format!("File {} already exists", name));
            }
        }
        OnDuplicate::Overwrite => {}
        OnDuplicate::Rename => {
            let mut i = 1;
            while target.exists() {
                let stem = crate::util::file_stem(name);
                let ext = crate::util::file_ext(name);
                let newname = if ext.is_empty() {
                    format!("{}-{}", stem, i)
                } else {
                    format!("{}-{}.{}", stem, i, ext)
                };
                target = base.join(newname);
                i += 1;
            }
        }
    }
    std::fs::write(&target, data).map_err(|e| format!("Failed to write file: {}", e))?;
    if let Some(mode) = c.chmod {
        use std::os::unix::fs::PermissionsExt;
        let _ = std::fs::set_permissions(&target, std::fs::Permissions::from_mode(mode));
    }
    Ok(())
}

pub fn form_param(body: &str, key: &str) -> Option<String> {
    for pair in body.split('&') {
        let mut it = pair.splitn(2, '=');
        let k = crate::http::url_decode(&it.next().unwrap_or("").replace('+', " "));
        if k == key {
            return Some(crate::http::url_decode(&it.next().unwrap_or("").replace('+', " ")));
        }
    }
    None
}

/// Split a multipart body into (headers, filename, data) triples.
pub fn split_multipart(body: &[u8], boundary: &str) -> Vec<Option<(String, Option<String>, Vec<u8>)>> {
    let delim = format!("--{}", boundary);
    let mut out = Vec::new();
    let delim_b = delim.as_bytes();
    let mut i = 0usize;
    let mut positions: Vec<usize> = Vec::new();
    while i + delim_b.len() <= body.len() {
        if &body[i..i + delim_b.len()] == delim_b {
            positions.push(i);
            i += delim_b.len();
        } else {
            i += 1;
        }
    }
    for w in positions.windows(2) {
        let start = w[0] + delim_b.len();
        let end = w[1];
        let chunk = &body[start..end];
        let chunk = chunk.strip_prefix(b"\r\n").unwrap_or(chunk);
        if chunk.starts_with(b"--") {
            continue;
        }
        if let Some(sep) = find(chunk, b"\r\n\r\n") {
            let headers = String::from_utf_lossy(&chunk[..sep]).to_string();
            let data = chunk[sep + 4..].to_vec();
            let data = data.strip_suffix(b"\r\n").unwrap_or(&data).to_vec();
            let filename = headers
                .lines()
                .find(|l| l.to_lowercase().starts_with("content-disposition"))
                .and_then(|l| {
                    let mut res = None;
                    for piece in l.split(';') {
                        let piece = piece.trim();
                        if let Some(r) = piece.strip_prefix("filename=") {
                            res = Some(r.trim_matches('"').to_string());
                        }
                    }
                    res
                });
            out.push(Some((headers, filename, data)));
        }
    }
    out
}

fn find(hay: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.len() > hay.len() {
        return None;
    }
    for i in 0..=(hay.len() - needle.len()) {
        if &hay[i..i + needle.len()] == needle {
            return Some(i);
        }
    }
    None
}

/// Handle POST requests to /rm (file deletion).
pub fn handle_rm(req: &Request, state: &Arc<ServeState>) -> Response {
    let c = &state.cfg;
    if c.rm_files.is_none() {
        return error(state, 404, &format!("Route {} could not be found", req.path));
    }
    let target = crate::handler::query_param(&req.query, "path").unwrap_or_default();
    let decoded = crate::http::url_decode(&target);
    let full = c.path.join(decoded.trim_start_matches('/'));
    let res = if full.is_dir() {
        std::fs::remove_dir_all(&full)
    } else {
        std::fs::remove_file(&full)
    };
    match res {
        Ok(_) => Response::text(200, "text/html", String::new()),
        Err(e) => error(state, 500, &format!("Failed to delete: {}", e)),
    }
}
