import subprocess,socket,time,os,sys,re,urllib.request,urllib.error,difflib,shutil
def freeport():
    s=socket.socket(); s.bind(('127.0.0.1',0)); p=s.getsockname()[1]; s.close(); return p
def req(port,path,method='GET',headers=None,data=None):
    url='http://127.0.0.1:%d%s'%(port,path)
    r=urllib.request.Request(url,method=method,data=data)
    if headers:
        for k,v in headers.items(): r.add_header(k,v)
    try: resp=urllib.request.urlopen(r)
    except urllib.error.HTTPError as e: resp=e
    hdrs=[(k.lower(),v if isinstance(v,bytes) else v.encode()) for k,v in resp.headers.items()]
    body=resp.read()
    return resp.status,hdrs,body
def start(binary,port,*args):
    cmd=[binary,'-p',str(port)]+list(args)
    log=open('/tmp/h/cmp_%d.log'%port,'wb')
    p=subprocess.Popen(cmd,cwd='/workspace',stdout=log,stderr=subprocess.STDOUT)
    time.sleep(0.7)
    return p
def norm(s,port):
    s=s.replace('127.0.0.1:%d'%port,'PORT')
    s=re.sub(r'20\d\d-\d\d-\d\d \d\d:\d\d:\d\d','DATE',s)
    s=re.sub(r'(now|\d+ (?:second|minute|hour|day|week|month|year)s? ago|a (?:second|minute|hour|day|week|month|year) ago|in .*)','HIST',s)
    return s
def compare(name,args,path,paths=None,post=None,headers=None):
    paths=paths or [path]
    results=[]
    for binary in ['/workspace/executable','/workspace/target/release/miniserve']:
        port=freeport()
        p=start(binary,port,*args)
        out=[]
        for pp in paths:
            try:
                st,h,b=req(port,pp,headers=headers,data=post)
                out.append((pp,st,h,b))
            except Exception as e:
                out.append((pp,None,None,repr(e).encode()))
        p.terminate(); p.wait()
        results.append((port,out))
    (p1,r1),(p2,r2)=results
    ok=True
    for (pp1,st1,h1,b1),(pp2,st2,h2,b2) in zip(r1,r2):
        if st1!=st2:
            print("%-22s %-30s STATUS %s vs %s"%(name,pp1,st1,st2)); ok=False; continue
        h1s=sorted((k.decode() if isinstance(k,bytes) else k, v.decode()) for k,v in h1)
        h2s=sorted((k.decode() if isinstance(k,bytes) else k, v.decode()) for k,v in h2)
        # ignore date header & content-length differences for streams
        h1s=[(k,v) for k,v in h1s if k!='date']
        h2s=[(k,v) for k,v in h2s if k!='date']
        if h1s!=h2s:
            print("%-22s %-30s HEADERS differ:"%(name,pp1))
            for a in h1s:
                if a not in h2s: print("    ref: %s"%str(a)[:120])
            for a in h2s:
                if a not in h1s: print("    min: %s"%str(a)[:120])
            ok=False
        n1=norm(b1.decode('utf-8','replace'),p1); n2=norm(b2.decode('utf-8','replace'),p2)
        if n1!=n2:
            print("%-22s %-30s BODY differs (%d vs %d bytes)"%(name,pp1,len(b1),len(b2)))
            sa=n1.split('><'); sb=n2.split('><')
            n=0
            for line in difflib.unified_diff(sa,sb,lineterm='',n=0):
                if line.startswith(('+','-')):
                    n+=1
                    if n<12: print("   ",line[:170])
            if n>=12: print("    ... (%d diffs)"%n)
            ok=False
    if ok: print("%-22s OK"%name)
    return ok
PY
echo ok"}

