/// used as the URL prefix of listing links.
pub fn encode_target(target: &str) -> String {
    let trailing = target.ends_with('/');
    let parts: Vec<String> = target
        .split('/')
        .filter(|p| !p.is_empty())
        .map(|p| percent_encode_path(p))
        .collect();
    let mut out = String::new();
    if target.starts_with('/') {
        out.push('/');
    }
    out.push_str(&parts.join("/"));
    if trailing && !out.ends_with('/') {
        out.push('/');
    }
    out
}

/// Percent encode a path (the set used by miniserve for listing links)""")
open(p,'w').write(s)
PY
