/// Value parser for `--header` values: `Name:Value` with a valid header name.
#[derive(Clone)]
pub struct HeaderValueParser;

fn is_token_char(c: char) -> bool {
    c.is_ascii_alphanumeric()
        || matches!(
            c,
            '!' | '#' | '$' | '%' | '&' | '\\'' | '*' | '+' | '-' | '.' | '^' | '_' | '`' | '|'
                | '~'
        )
}

impl clap::builder::TypedValueParser for HeaderValueParser {
    type Value = String;

    fn parse_ref(
        &self,
        cmd: &clap::Command,
        arg: Option<&clap::builder::Arg>,
        value: &std::ffi::OsStr,
    ) -> Result<String, clap::Error> {
        let s = value.to_string_lossy().into_owned();
        let name = s.split(':').next().unwrap_or("");
        if name.is_empty() || !name.chars().all(is_token_char) {
            return Err(clap::Error::value_validation(
                arg.map(|a| a.to_string()).unwrap_or_default(),
                "invalid header name".to_string(),
            ));
        }
        Ok(s)
    }
}
