use crate::http::{Body, Request, Response};
use crate::server::ServeState;
use std::sync::Arc;

pub fn handle_download(
    req: &Request,
    state: &Arc<ServeState>,
    path: &std::path::Path,
    _target: &str,
    kind: &str,
) -> Response {
    let c = &state.cfg;
    let enabled = match kind {
        "tar" => c.enable_tar,
        "tar_gz" => c.enable_tar_gz,
        "zip" => c.enable_zip,
        _ => false,
    };
    if !enabled {
        let msg = "Archive creation is disabled.".to_string();
        crate::log_error(&msg);
        return Response::text(
            403,
            "text/html",
            crate::render::render_error(state, 403, &msg, true, "/"),
        );
    }
    let base = path
        .file_name()
        .map(|n| n.to_string_lossy().to_string())
        .unwrap_or_default();
    let ext = match kind {
        "tar" => "tar",
        "tar_gz" => "tar.gz",
        _ => "zip",
    };
    let name = format!("{}.{}", base, ext);
    let content_type = match kind {
        "tar" => "application/tar",
        "tar_gz" => "application/gzip",
        _ => "application/zip",
    };
    let dir_path = path.to_path_buf();
    let kind_owned = kind.to_string();
    Response {
        status: 200,
        headers: vec![
            ("content-type".into(), content_type.into()),
            (
                "content-transfer-encoding".into(),
                "binary".into(),
            ),
            (
                "content-disposition".into(),
                format!("attachment; filename=\"{}\"", crate::render::quote_filename(&name)),
            ),
        ],
        body: Body::Stream(Box::new(move |w: &mut dyn std::io::Write| {
            match kind_owned.as_str() {
                "tar" => {
                    let data = build_tar(&dir_path);
                    w.write_all(&data)
                }
                "tar_gz" => {
                    let data = build_tar(&dir_path);
                    let gz = gzip_wrap(&data);
                    w.write_all(&gz)
                }
                _ => {
                    let data = build_zip(&dir_path);
                    w.write_all(&data)
                }
            }
        })),
        no_length: false,
    }
}

struct TarEntry {
    name: String,
    is_dir: bool,
    size: u64,
    mode: u32,
    uid: u64,
    gid: u64,
    mtime: u64,
    data: Vec<u8>,
}

fn entries_recursive(
    dir: &std::path::Path,
    prefix: &str,
    out: &mut Vec<TarEntry>,
) -> Result<(), ()> {
    let mut list: Vec<std::fs::DirEntry> = match std::fs::read_dir(dir) {
        Ok(r) => r.flatten().collect(),
        Err(_) => return Err(()),
    };
    // tar iterates the directory in reverse order, recursing right after each directory
    list.reverse();
    for e in list {
        let full = e.path();
        let name = if prefix.is_empty() {
            e.file_name().to_string_lossy().to_string()
        } else {
            format!("{}/{}", prefix, e.file_name().to_string_lossy())
        };
        let md = match std::fs::metadata(&full) {
            Ok(m) => m,
            Err(_) => return Err(()),
        };
        use std::os::unix::fs::MetadataExt;
        let mode = md.mode() & 0o7777;
        let uid = md.uid();
        let gid = md.gid();
        let mtime = md
            .modified()
            .ok()
            .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
            .map(|d| d.as_secs())
            .unwrap_or(0);
        if md.is_dir() {
            out.push(TarEntry {
                name: name.clone(),
                is_dir: true,
                size: 0,
                mode: mode | 0o40000,
                uid,
                gid,
                mtime,
                data: Vec::new(),
            });
            entries_recursive(&full, &name, out)?;
        } else {
            let data = std::fs::read(&full).map_err(|_| ())?;
            out.push(TarEntry {
                name,
                is_dir: false,
                size: data.len() as u64,
                mode: mode | 0o100000,
                uid,
                gid,
                mtime,
                data,
            });
        }
    }
    Ok(())
}

fn write_octal_nul(buf: &mut [u8], val: u64) {
    // buf.len() - 1 digits, NUL terminated
    let n = buf.len();
    let digits = n - 1;
    let s = format!("{:0width$o}", val, width = digits);
    let sb = s.as_bytes();
    let start = if sb.len() > digits { sb.len() - digits } else { 0 };
    for i in 0..digits {
        buf[i] = if sb.len() > digits {
            sb[start + i]
        } else {
            let pad = digits - sb.len();
            if i < pad {
                b'0'
            } else {
                sb[i - pad]
            }
        };
    }
    buf[digits] = 0;
}

fn tar_header(e: &TarEntry) -> [u8; 512] {
    let mut h = [0u8; 512];
    let name_bytes = e.name.as_bytes();
    if name_bytes.len() <= 100 {
        h[..name_bytes.len()].copy_from_slice(name_bytes);
    } else {
        // ustar: split into prefix + name
        let split = name_bytes.len() - 100;
        let mut cut = split;
        while cut < name_bytes.len() && name_bytes[cut] != b'/' {
            cut += 1;
        }
        let (prefix, rest) = name_bytes.split_at(cut + 1);
        let pl = prefix.len().min(155);
        h[345..345 + pl].copy_from_slice(&prefix[..pl]);
        let rl = rest.len().min(100);
        h[..rl].copy_from_slice(&rest[..rl]);
    }
    write_octal_nul(&mut h[100..108], (e.mode & 0o7777) as u64);
    write_octal_nul(&mut h[108..116], e.uid);
    write_octal_nul(&mut h[116..124], e.gid);
    write_octal_nul(&mut h[124..136], e.size);
    write_octal_nul(&mut h[136..148], e.mtime);
    h[156] = if e.is_dir { b'5' } else { b'0' };
    h[257..263].copy_from_slice(b"ustar ");
    h[263] = b' ';
    h[264] = 0;
    let mut checksum: u64 = 0;
    for (i, &b) in h.iter().enumerate() {
        checksum += if (148..156).contains(&i) { 0x20 } else { b as u64 };
    }
    write_octal_nul(&mut h[148..156], checksum);
    h
}

/// Build an uncompressed tar archive of a directory.
pub fn build_tar(path: &std::path::Path) -> Vec<u8> {
    let mut out: Vec<u8> = Vec::new();
    let base = path
        .file_name()
        .map(|n| n.to_string_lossy().to_string())
        .unwrap_or_default();
    let mut entries: Vec<TarEntry> = Vec::new();
    if let Ok(md) = std::fs::metadata(path) {
        use std::os::unix::fs::MetadataExt;
        let mtime = md
            .modified()
            .ok()
            .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
            .map(|d| d.as_secs())
            .unwrap_or(0);
        entries.push(TarEntry {
            name: format!("{}/", base),
            is_dir: true,
            size: 0,
            mode: (md.mode() & 0o7777) | 0o40000,
            uid: md.uid(),
            gid: md.gid(),
            mtime,
            data: Vec::new(),
        });
    }
    let _ = entries_recursive(path, "", &mut entries);
    for e in &entries {
        let header = tar_header(e);
        out.extend_from_slice(&header);
        if !e.is_dir {
            out.extend_from_slice(&e.data);
            let pad = (512 - (e.data.len() % 512)) % 512;
            out.extend(std::iter::repeat(0u8).take(pad));
        }
    }
    out.extend(std::iter::repeat(0u8).take(1024));
    out
}

/// Wrap raw deflate data in a gzip container matching the reference implementation.
pub fn gzip_wrap(data: &[u8]) -> Vec<u8> {
    let mut out: Vec<u8> = Vec::new();
    let now = crate::now_secs() as u32;
    out.extend_from_slice(&[0x1f, 0x8b, 0x08, 0x00]);
    out.extend_from_slice(&now.to_le_bytes());
    out.push(0x00); // XFL
    out.push(0x03); // OS: Unix
    let deflated = crate::util::deflate_raw(data);
    out.extend_from_slice(&deflated);
    let mut h = crc32fast::Hasher::new();
    h.update(data);
    let crc = h.finalize();
    out.extend_from_slice(&crc.to_le_bytes());
    out.extend_from_slice(&(data.len() as u32).to_le_bytes());
    out
}

struct ZipEntry {
    name: String,
    is_dir: bool,
    crc: u32,
    data: Vec<u8>,
    offset: u32,
}

fn zip_collect(dir: &std::path::Path, prefix: &str, out: &mut Vec<ZipEntry>) {
    let mut queue: Vec<std::path::PathBuf> = Vec::new();
    let mut names: Vec<(String, std::path::PathBuf)> = Vec::new();
    if let Ok(rd) = std::fs::read_dir(dir) {
        for e in rd.flatten() {
            let name = if prefix.is_empty() {
                e.file_name().to_string_lossy().to_string()
            } else {
                format!("{}/{}", prefix, e.file_name().to_string_lossy())
            };
            names.push((name, e.path()));
        }
    }
    for (name, full) in names {
        let md = match std::fs::metadata(&full) {
            Ok(m) => m,
            Err(_) => continue,
        };
        if md.is_dir() {
            out.push(ZipEntry {
                name: format!("{}/", name),
                is_dir: true,
                crc: 0,
                data: Vec::new(),
                offset: 0,
            });
            queue.push(full);
        } else {
            let data = std::fs::read(&full).unwrap_or_default();
            let crc = crc32(data);
            out.push(ZipEntry {
                name,
                is_dir: false,
                crc,
                data,
                offset: 0,
            });
        }
    }
    for q in queue {
        let base = q
            .file_name()
            .map(|n| n.to_string_lossy().to_string())
            .unwrap_or_default();
        let next_prefix = if prefix.is_empty() {
            base
        } else {
            format!("{}/{}", prefix, base)
        };
        zip_collect(&q, &next_prefix, out);
    }
}

fn write_le16(out: &mut Vec<u8>, v: u16) {
    out.extend_from_slice(&v.to_le_bytes());
}
fn write_le32(out: &mut Vec<u8>, v: u32) {
    out.extend_from_slice(&v.to_le_bytes());
}

/// Build a zip archive (stored entries) of a directory.
pub fn build_zip(path: &std::path::Path) -> Vec<u8> {
    let base = path
        .file_name()
        .map(|n| n.to_string_lossy().to_string())
        .unwrap_or_default();
    let mut entries: Vec<ZipEntry> = Vec::new();
    zip_collect(path, "", &mut entries);
    let mut out: Vec<u8> = Vec::new();
    let mut central: Vec<u8> = Vec::new();
    for e in entries.iter_mut() {
        e.offset = out.len() as u32;
        let name = format!("{}/{}", base, e.name);
