        .file_name()
        .map(|n| n.to_string_lossy().to_string())
        .unwrap_or_default();
    let mut entries: Vec<TarEntry> = Vec::new();
    if let Ok(md) = std::fs::metadata(path) {
        use std::os::unix::fs::MetadataExt;
        let mtime = md
            .modified()
            .ok()
            .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
            .map(|d| d.as_secs())
            .unwrap_or(0);
        entries.push(TarEntry {
            name: format!("{}/", base),
            is_dir: true,
            size: 0,
            mode: (md.mode() & 0o7777) | 0o40000,
            uid: md.uid(),
            gid: md.gid(),
            mtime,
            data: Vec::new(),
        });
    }
    let _ = entries_recursive(path, "", &mut entries);
    for e in &entries {
        let header = tar_header(e);
        out.extend_from_slice(&header);
        if !e.is_dir {
            out.extend_from_slice(&e.data);
            let pad = (512 - (e.data.len() % 512)) % 512;
            out.extend(std::iter::repeat(0u8).take(pad));
        }
    }
    out.extend(std::iter::repeat(0u8).take(1024));
    out
}

/// Wrap raw deflate data in a gzip container matching the reference implementation.
pub fn gzip_wrap(data: &[u8]) -> Vec<u8> {
    let mut out: Vec<u8> = Vec::new();
    let now = crate::now_secs() as u32;
    out.extend_from_slice(&[0x1f, 0x8b, 0x08, 0x00]);
    out.extend_from_slice(&now.to_le_bytes());
    out.push(0x00); // XFL
    out.push(0x03); // OS: Unix
    let deflated = crate::util::deflate_raw(data);
    out.extend_from_slice(&deflated);
    let mut h = crc32fast::Hasher::new();
    h.update(data);
    let crc = h.finalize();
    out.extend_from_slice(&crc.to_le_bytes());
    out.extend_from_slice(&(data.len() as u32).to_le_bytes());
    out
}

struct ZipEntry {
    name: String,
    is_dir: bool,
    crc: u32,
    data: Vec<u8>,
    offset: u32,
}

fn zip_collect(dir: &std::path::Path, prefix: &str, out: &mut Vec<ZipEntry>) {
    let mut queue: Vec<std::path::PathBuf> = Vec::new();
    let mut names: Vec<(String, std::path::PathBuf)> = Vec::new();
    if let Ok(rd) = std::fs::read_dir(dir) {
        for e in rd.flatten() {
            let name = if prefix.is_empty() {
                e.file_name().to_string_lossy().to_string()
            } else {
                format!("{}/{}", prefix, e.file_name().to_string_lossy())
            };
            names.push((name, e.path()));
        }
    }
    for (name, full) in names {
        let md = match std::fs::metadata(&full) {
            Ok(m) => m,
            Err(_) => continue,
        };
        if md.is_dir() {
            out.push(ZipEntry {
                name: format!("{}/", name),
                is_dir: true,
                crc: 0,
                data: Vec::new(),
                offset: 0,
            });
            queue.push(full);
        } else {
            let data = std::fs::read(&full).unwrap_or_default();
            let crc = crc32(data);
            out.push(ZipEntry {
                name,
                is_dir: false,
                crc,
                data,
                offset: 0,
            });
        }
    }
    for q in queue {
        let base = q
            .file_name()
            .map(|n| n.to_string_lossy().to_string())
            .unwrap_or_default();
        let next_prefix = if prefix.is_empty() {
            base
        } else {
            format!("{}/{}", prefix, base)
        };
        zip_collect(&q, &next_prefix, out);
    }
}

fn write_le16(out: &mut Vec<u8>, v: u16) {
    out.extend_from_slice(&v.to_le_bytes());
}
fn write_le32(out: &mut Vec<u8>, v: u32) {
    out.extend_from_slice(&v.to_le_bytes());
}

/// Build a zip archive (stored entries) of a directory.
pub fn build_zip(path: &std::path::Path) -> Vec<u8> {
    let base = path
        .file_name()
        .map(|n| n.to_string_lossy().to_string())
        .unwrap_or_default();
    let mut entries: Vec<ZipEntry> = Vec::new();
    zip_collect(path, "", &mut entries);
    let mut out: Vec<u8> = Vec::new();
    let mut central: Vec<u8> = Vec::new();
    for e in entries.iter_mut() {
        e.offset = out.len() as u32;
        let name = format!("{}/{}", base, e.name);
        let name_b = name.as_bytes();
        out.extend_from_slice(&[0x50, 0x4b, 0x03, 0x04]);
        write_le16(&mut out, if e.is_dir { 20 } else { 10 });
        write_le16(&mut out, 0);
        write_le16(&mut out, 0);
        write_le16(&mut out, 0);
        write_le16(&mut out, 0x0021);
        write_le32(&mut out, if e.is_dir { 0 } else { e.crc });
        write_le32(&mut out, e.data.len() as u32);
        write_le32(&mut out, e.data.len() as u32);
        write_le16(&mut out, name_b.len() as u16);
        write_le16(&mut out, 0);
        out.extend_from_slice(name_b);
        out.extend_from_slice(&e.data);

        central.extend_from_slice(&[0x50, 0x4b, 0x01, 0x02]);
        write_le16(&mut central, if e.is_dir { 788 } else { 778 });
        write_le16(&mut central, if e.is_dir { 20 } else { 10 });
        write_le16(&mut central, 0);
        write_le16(&mut central, 0);
        write_le16(&mut central, 0);
        write_le16(&mut central, 0x0021);
        write_le32(&mut central, if e.is_dir { 0 } else { e.crc });
        write_le32(&mut central, e.data.len() as u32);
        write_le32(&mut central, e.data.len() as u32);
        write_le16(&mut central, name_b.len() as u16);
        write_le16(&mut central, 0);
        write_le16(&mut central, 0);
        write_le16(&mut central, 0);
        write_le16(&mut central, 0);
        write_le32(&mut central, if e.is_dir {
            0o40755u32 << 16
        } else {
            0o100644u32 << 16
        });
        write_le32(&mut central, e.offset);
        central.extend_from_slice(name_b);
    }
    let cd_offset = out.len() as u32;
    let cd_size = central.len() as u32;
    out.extend_from_slice(&central);
    out.extend_from_slice(&[0x50, 0x4b, 0x05, 0x06]);
    write_le16(&mut out, 0);
    write_le16(&mut out, 0);
    write_le16(&mut out, entries.len() as u16);
    write_le16(&mut out, entries.len() as u16);
    write_le32(&mut out, cd_size);
    write_le32(&mut out, cd_offset);
    write_le16(&mut out, 0);
    out
}

pub fn crc32(data: &[u8]) -> u32 {
    let mut h = crc32fast::Hasher::new();
    h.update(data);
    h.finalize()
}
