use crate::http::{Body, Request, Response};
use crate::server::ServeState;
use std::path::PathBuf;
use std::sync::Arc;

fn listing_response(req: &Request, state: &Arc<ServeState>) -> Response {
    crate::handler::listing_for(&req, state, "/")
}

fn plain_error(status: u16, msg: &str) -> Response {
    crate::log_error(msg);
    Response {
        status,
        headers: vec![(
            "content-type".into(),
            "text/plain; charset=utf-8".into(),
        )],
        body: Body::Full(msg.as_bytes().to_vec()),
        no_length: false,
    }
}

/// Validate the `path` query parameter the way miniserve does.
fn validate_path(
    state: &Arc<ServeState>,
    raw: &str,
) -> Result<PathBuf, Response> {
    if !raw.starts_with('/') {
        return Err(plain_error(
            400,
            "Invalid HTTP request\ncaused by: Invalid value for 'path' parameter",
        ));
    }
    let decoded = crate::http::url_decode(raw);
    let full = state.cfg.path.join(decoded.trim_start_matches('/'));
    if !full.exists() {
        return Err(plain_error(
            400,
            "Invalid HTTP request\ncaused by: Invalid value for 'path' parameter",
        ));
    }
    Ok(full)
}

/// Handle POST requests to /upload (file uploads and directory creation).
pub fn handle_upload(req: &Request, state: &Arc<ServeState>) -> Response {
    let c = &state.cfg;
    if c.upload_files.is_none() {
        crate::log_error(&format!("Route {} could not be found", crate::handler::raw_path(req)));
        return crate::handler::not_found_page(state, &crate::handler::raw_path(req));
    }
    let raw = match crate::handler::query_param(&req.query, "path") {
        Some(v) => v,
        None => {
            return plain_error(
                400,
                "Query deserialize error: missing field `path`",
            )
        }
    };
    if raw.is_empty() {
        crate::log_error("Route / could not be found");
        return crate::handler::not_found_page(state, "/");
    }
    let full = match validate_path(state, &raw) {
        Ok(f) => f,
        Err(e) => return e,
    };
    // check the upload directory permission
    if let Some(Some(allowed)) = &c.upload_files {
        let allowed = format!("/{}", allowed.to_string_lossy().trim_start_matches('/'));
        let norm = crate::util::normalize_rel(&decoded_or(raw));
        if !(norm == allowed || norm.starts_with(&format!("{}/", allowed.trim_end_matches('/')))) {
            return plain_error(403, "Upload not allowed to this directory");
        }
    }
    if !full.is_dir() {
        return plain_error(
            400,
            &format!(
                "Invalid path\ncaused by: cannot upload file to {}, since it's not a directory",
                full.display()
            ),
        );
    }
    if std::fs::read_dir(&full).map(|mut d| d.next().is_none()).unwrap_or(true) {
        return plain_error(
            400,
            "Invalid HTTP request\ncaused by: Invalid value for 'path' parameter",
        );
    }
    let ctype = req.header("content-type").unwrap_or("").to_string();
    if !ctype.starts_with("multipart/form-data") {
        return plain_error(
            400,
            "Failed to process multipart request\ncaused by: ContentTypeIncompatible",
        );
    }
    let boundary = match ctype
        .split(';')
        .map(|s| s.trim())
        .find(|s| s.starts_with("boundary="))
    {
        Some(b) => b[9..].trim_matches('"').to_string(),
        None => {
            return plain_error(
                400,
                "Failed to process multipart request\ncaused by: ContentTypeIncompatible",
            )
        }
    };
    let parts = split_multipart(&req.body, &boundary);
    let mut dir_name: Option<String> = None;
    for part in parts.into_iter().flatten() {
        let (headers, filename, data) = part;
        let name_field = header_field(&headers, "name");
        if name_field.as_deref() == Some("mkdir") {
            if filename.is_some() {
                continue;
            }
            dir_name = Some(String::from_utf8_lossy(&data).into_owned());
            continue;
        }
        let filename = match filename {
            Some(f) if !f.is_empty() => f,
            _ => continue,
        };
        if crate::handler::query_param(&req.query, "path").is_none() {
            continue;
        }
        let target_dir = full.clone();
        if let Err(e) = write_uploaded_file(state, &target_dir, &filename, &data) {
            return e;
        }
    }
    if let Some(dn) = dir_name {
        if let Err(e) = handle_mkdir(state, &full, &dn) {
            return e;
        }
    }
    listing_response(req, state)
}

fn decoded_or(raw: &str) -> String {
    crate::http::url_decode(raw)
}

fn header_field(headers: &str, name: &str) -> Option<String> {
    for line in headers.lines() {
        let lower = line.to_lowercase();
        if lower.starts_with(&format!("content-disposition")) {
            for piece in line.split(';') {
                let piece = piece.trim();
                if let Some(rest) = piece.strip_prefix(&format!("{}=", name)) {
                    return Some(rest.trim_matches('"').to_string());
                }
            }
        }
    }
    None
}

fn handle_mkdir(state: &Arc<ServeState>, base: &std::path::Path, name: &str) -> Result<(), Response> {
    if name.is_empty() {
        return Err(plain_error(
            400,
            "Failed to parse Failed to parse 'mkdir' path\ncaused by: ",
        ));
    }
    let target = base.join(crate::http::url_decode(name));
    if let Err(e) = std::fs::create_dir_all(&target) {
        return Err(plain_error(500, &format!("Failed to create directory: {}", e)));
    }
    if let Some(mode) = state.cfg.chmod {
        use std::os::unix::fs::PermissionsExt;
        let _ = std::fs::set_permissions(&target, std::fs::Permissions::from_mode(mode));
    }
    Ok(())
}

fn write_uploaded_file(
    state: &Arc<ServeState>,
    dir: &std::path::Path,
    name: &str,
    data: &[u8],
) -> Result<(), Response> {
    let c = &state.cfg;
    let base = crate::http::url_decode(name);
    let mut target = dir.join(&base);
    match c.on_duplicate_files {
        OnDuplicate::Error => {
            if target.exists() {
                return Err(plain_error(
                    409,
                    "File already exists, and the on_duplicate_files option is set to error out",
                ));
            }
        }
        OnDuplicate::Overwrite => {}
        OnDuplicate::Rename => {
            let mut i = 1;
            while target.exists() {
                let stem = crate::util::file_stem(&base);
                let ext = crate::util::file_ext(&base);
                let newname = if ext.is_empty() {
                    format!("{}-{}", stem, i)
                } else {
                    format!("{}-{}.{}", stem, i, ext)
                };
                target = dir.join(newname);
                i += 1;
            }
        }
    }
    if let Err(e) = std::fs::write(&target, data) {
        return Err(plain_error(500, &format!("Failed to write file: {}", e)));
    }
    if let Some(mode) = c.chmod {
        use std::os::unix::fs::PermissionsExt;
        let _ = std::fs::set_permissions(&target, std::fs::Permissions::from_mode(mode));
    }
    Ok(())
}

/// Split a multipart body into (headers, filename, data) triples.
pub fn split_multipart(
    body: &[u8],
    boundary: &str,
) -> Vec<Option<(String, Option<String>, Vec<u8>)>> {
    let delim = format!("--{}", boundary);
    let delim_b = delim.as_bytes();
    let mut positions: Vec<usize> = Vec::new();
    let mut i = 0usize;
    while i + delim_b.len() <= body.len() {
        if &body[i..i + delim_b.len()] == delim_b {
            positions.push(i);
            i += delim_b.len();
        } else {
            i += 1;
        }
    }
    let mut out = Vec::new();
    for w in positions.windows(2) {
        let start = w[0] + delim_b.len();
        let end = w[1];
        let chunk = &body[start..end];
        let chunk = chunk.strip_prefix(b"\r\n").unwrap_or(chunk);
        if chunk.starts_with(b"--") {
            continue;
        }
        if let Some(sep) = find(chunk, b"\r\n\r\n") {
            let headers = String::from_utf8_lossy(&chunk[..sep]).into_owned();
            let mut data = chunk[sep + 4..].to_vec();
            if data.ends_with(b"\r\n") {
                data.truncate(data.len() - 2);
            }
            let filename = headers
                .lines()
                .find(|l| l.to_lowercase().starts_with("content-disposition"))
                .and_then(|l| {
                    let mut res = None;
                    for piece in l.split(';') {
                        let piece = piece.trim();
                        if let Some(r) = piece.strip_prefix("filename=") {
                            res = Some(r.trim_matches('"').to_string());
                        }
                    }
                    res
                });
            out.push(Some((headers, filename, data)));
        }
    }
    out
}

fn find(hay: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.len() > hay.len() {
        return None;
    }
    for i in 0..=(hay.len() - needle.len()) {
        if &hay[i..i + needle.len()] == needle {
            return Some(i);
        }
    }
    None
}

/// Handle POST requests to /rm (file deletion).
pub fn handle_rm(req: &Request, state: &Arc<ServeState>) -> Response {
    let c = &state.cfg;
    if c.rm_files.is_none() {
        return crate::handler::not_found_page(state, &crate::handler::raw_path(req));
    }
    let raw = match crate::handler::query_param(&req.query, "path") {
        Some(v) => v,
        None => {
            let body = crate::render::render_error(
                state,
                400,
                "Query deserialize error: missing field `path`",
                true,
                "/",
            );
            return Response::text(400, "text/html", body);
        }
    };
    if raw.is_empty() {
        return crate::handler::not_found_page(state, "/");
    }
    let full = match validate_path(state, &raw) {
        Ok(f) => f,
        Err(e) => {
            // the rm errors are rendered as HTML pages
            let msg = match &e.body {
                Body::Full(b) => String::from_utf8_lossy(b).into_owned(),
                _ => String::new(),
            };
            let body = crate::render::render_error(state, e.status, &msg, true, "/");
            return Response::text(e.status, "text/html", body);
        }
    };
    if let Some(Some(allowed)) = &c.rm_files {
        let allowed = format!("/{}", allowed.to_string_lossy().trim_start_matches('/'));
        let norm = crate::util::normalize_rel(&decoded_or(&raw));
        if !(norm == allowed || norm.starts_with(&format!("{}/", allowed.trim_end_matches('/')))) {
            let body = crate::render::render_error(
                state,
                403,
                "Remove not allowed to this directory",
                true,
                "/",
            );
            return Response::text(403, "text/html", body);
        }
    }
    if full.is_dir() {
        let _ = std::fs::remove_dir_all(&full);
    } else {
        let _ = std::fs::remove_file(&full);
    }
    listing_response(req, state)
}
