/// Extract the `DirSize` value from the JSON body of the directory size API,
/// reporting serde-like error messages.
pub fn parse_dirsize_json(body: &str) -> Result<String, String> {
    let t = body.trim_start();
    if t.is_empty() {
        return Err("EOF while parsing a value at line 1 column 0".to_string());
    }
    if !t.starts_with('{') {
        return Err("expected value at line 1 column 1".to_string());
    }
    // find the first key
    let rest = &t[1..];
    let rest = rest.trim_start();
    if !rest.starts_with('"') {
        return Err("key must be a string at line 1 column 2".to_string());
    }
    let key_end = match rest[1..].find('"') {
        Some(i) => i + 2,
        None => return Err("EOF while parsing a string at line 1 column 1".to_string()),
    };
    let key = &rest[1..key_end - 1];
    let after = &rest[key_end..];
    let after = after.trim_start();
    if !after.starts_with(':') {
        return Err(format!(
            "expected `:` at line 1 column {}",
            key_end + 1 + (rest.len() - after.len())
        ));
    }
    let after = after[1..].trim_start();
    let offset = t.len() - after.len();
    if !after.starts_with('"') {
        return Err(format!(
            "invalid type: expected a string at line 1 column {}",
            offset
        ));
    }
    let val_end = match after[1..].find('"') {
        Some(i) => i + 1,
        None => return Err("EOF while parsing a string at line 1 column 1".to_string()),
    };
    let value = &after[1..val_end];
    if key != "DirSize" {
        return Err(format!(
            "unknown variant `{}`, expected `DirSize` at line 1 column {}",
            key,
            key_end + 1
        ));
    }
    Ok(value.to_string())
}
